9\u043d\u043e\u0441\u0442\u0438 \u0438 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u0431\u0435\u0437 \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u043f\u0430\u043a\u0435\u0442\u043e\u0432 (pure-python \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u041c\u0430\u043a\u041demar/\u0431\u0443\u0441\u0442\u0432\u0440\u0435\u043f \u0440\u0435\u0430\u043b\u0438\u0437\u0443\u0435\u043c\u044b).\n- 224 \u044f\u0434\u0440\u0430 CPU, ~2 \u0422\u0411 RAM, ~39 \u0413\u0411 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u043d\u0430 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 workspace. GPU \u043d\u0435\u0442.\n\n**\u041d\u0435\u0442 (\u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430\u043c\u0438):**\n- \u0421\u0435\u0442\u0438: `Network is unreachable` (\u043f\u0440\u044f\u043c\u043e\u0439 TCP-\u0442\u0435\u0441\u0442). \u0421\u043a\u0430\u0447\u0438\u0432\u0430\u043d\u0438\u0435 \u0434\u0430\u043d\u043d\u044b\u0445/\u043c\u043e\u0434\u0435\u043b\u0435\u0439/\u043f\u0430\u043a\u0435\u0442\u043e\u0432 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e.\n- \u0414\u0430\u0442\u0430\u0441\u0435\u0442\u043e\u0432, \u0434\u0430\u043c\u043f\u043e\u0432 (Wikidata \u0438 \u0442.\u043f.), \u0444\u0430\u0439\u043b\u043e\u0432 \u043f\u0430\u0440 \u2014 \u043d\u0438\u043a\u0430\u043a\u0438\u0445.\n- \u041d\u0430\u0443\u0447\u043d\u044b\u0445 \u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a (numpy/scipy/pandas/sklearn/statsmodels/torch/transformers) \u0438 LLM-\u0431\u0438\u0431\u043b\u0438\u043e\u0442\u0435\u043a/\u0432\u0435\u0441\u043e\u043e\u0431\u0449\u0435\u0441\u0442\u0432 (.gguf, HF-\u043a\u044d\u0448) \u2014 \u043d\u0438\u043a\u0430\u043a\u0438\u0445; `~` \u0438 \u043a\u044d\u0448\u0438 \u043f\u0443\u0441\u0442\u044b.\n- \u0422\u0440\u0435\u043a\u043e\u0432, \u043f\u0440\u043e\u0448\u043b\u044b\u0445 \u0441\u043a\u0440\u0438\u043f\u0442\u043e\u0432, \u0437\u0430\u043c\u0435\u0440\u043e\u0432, \u043f\u0438\u043b\u043e\u0442\u043e\u0432.\n\n**\u0412\u044b\u0432\u043e\u0434 \u043f\u043e \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u0438:** \u0442\u0435\u043a\u0443\u0449\u0438\u0439 \u0431\u043e\u043a\u0441 \u043f\u0440\u0438\u0433\u043e\u0434\u0435\u043d \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u0438 \u043d\u0430\u043f\u0438\u0441\u0430\u043d\u0438\u044f \u043a\u043e\u0434\u0430-\u0437\u0430\u0433\u043e\u0442\u043e\u0432\u043e\u043a (\u0441\u0431\u043e\u0440\u043a\u0430 \u0441\u0442\u0438\u043c\u0443\u043b\u043e\u0432 \u0438\u0437 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u043d\u043e\u0433\u043e CSV, \u0441\u043a\u043e\u0440\u0438\u043d\u0433, \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u043d\u0430 stdlib). \u0417\u0430\u043f\u0443\u0441\u043a \u0441\u0430\u043c\u043e\u0433\u043e \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0432\u043d\u0435\u0448\u043d\u0438\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432, \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0437\u0434\u0435\u0441\u044c \u043d\u0435\u0442: (\u0430) \u0441\u043b\u0435\u043f\u043e\u043a \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445 (\u0444\u0430\u0439\u043b \u043f\u0430\u0440 \u00ab\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u2014\u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb + \u043c\u0435\u0442\u0430\u0434\u0430\u043d\u043d\u044b\u0435 \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u0438), (\u0431) \u0434\u043e\u0441\u0442\u0443\u043f \u043a \u043c\u043e\u0434\u0435\u043b\u044f\u043c \u2014 API (\u043d\u0443\u0436\u043d\u0430 \u0441\u0435\u0442\u044c) \u0438\u043b\u0438 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u0435\u0441\u0430 (\u043d\u0443\u0436\u043d\u044b \u0444\u0430\u0439\u043b\u044b; CPU-\u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441 \u043c\u0430\u043b\u044b\u0445 7\u20138B \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u0435\u043d \u043d\u0430 224 \u044f\u0434\u0440\u0430\u0445, \u043d\u043e \u0432\u0435\u0441\u043e\u0432 \u043d\u0435\u0442; GPU-\u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0440\u0435\u0441\u0443\u0440\u0441\u0430). \u041f\u043b\u0430\u043d \u043d\u0438\u0436\u0435 \u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u00ab\u0433\u043e\u0442\u043e\u0432\u044b\u0439 \u043a \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044e \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0435 \u044d\u0442\u0438\u0445 \u0434\u0432\u0443\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432\u00bb.\n\n## \u041f\u0420\u0415\u0414\u041b\u0410\u0413\u0410\u0415\u041c\u042b\u0419 \u041f\u041e\u0414\u0425\u041e\u0414 (\u0442\u043e\u043b\u044c\u043a\u043e \u043f\u043b\u0430\u043d)\n\n**\u0413\u0438\u043f\u043e\u0442\u0435\u0437\u0430:** \u0434\u043b\u044f \u0444\u0430\u043a\u0442\u043e\u0432 \u00ab\u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u044c \u2014 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c/\u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb \u043c\u043e\u0434\u0435\u043b\u044c \u0442\u043e\u0447\u043d\u0435\u0435 \u0438\u0437\u0432\u043b\u0435\u043a\u0430\u0435\u0442 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u0440\u0435\u0431\u0451\u043d\u043a\u0430 (\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 R: \u0440\u0435\u0431\u0451\u043d\u043e\u043a\u2192\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c), \u0447\u0435\u043c \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f (\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 P: \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u2192\u0440\u0435\u0431\u0451\u043d\u043e\u043a).\n\n**1) \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u043f\u0430\u0440 \u0438 \u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u044f.**\nWikidata \u043a\u0430\u043a \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0438\u0441\u0442\u0438\u043d\u044b: \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 P3373 (father), P6/P7 (father/mother), \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0435 P40 (child). \u041e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u044f: (i) \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0441 \u0434\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u043c\u0435\u0442\u043a\u043e\u0439 \u0432\u0440\u0435\u043c\u0435\u043d\u0438 (\u0441\u043d\u0438\u043c\u043e\u043a \u0434\u0430\u043c\u043f\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442 \u00ab\u0438\u0441\u0442\u0438\u043d\u0443 \u043d\u0430 \u0434\u0430\u0442\u0443\u00bb), \u0447\u0442\u043e \u043a\u0440\u0438\u0442\u0438\u0447\u043d\u043e \u0434\u043b\u044f \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0441 cutoff \u0437\u043d\u0430\u043d\u0438\u0439 \u043c\u043e\u0434\u0435\u043b\u0438; (ii) \u0432\u0441\u0442\u0440\u043e\u0435\u043d\u043d\u044b\u0435 \u043c\u0435\u0442\u0430\u0434\u0430\u043d\u043d\u044b\u0435 \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u0438\u0441\u043a\u0430\u0436\u0435\u043d\u0438\u0439 \u2014 \u0447\u0438\u0441\u043b\u043e sitelinks (\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c), aliases/\u043c\u0435\u0442\u043a\u0438 \u043d\u0430 \u0432\u0441\u0435\u0445 \u044f\u0437\u044b\u043a\u0430\u0445 (\u0432\u0430\u0440\u0438\u0430\u043d\u0442\u044b \u0438\u043c\u0451\u043d), P40 \u0434\u043b\u044f \u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0443\u0447\u0451\u0442\u0430 \u0447\u0438\u0441\u043b\u0430 \u0434\u0435\u0442\u0435\u0439; (iii) \u043b\u0438\u0446\u0435\u043d\u0437\u0438\u044f CC0, \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c. \u041e\u0442\u0431\u043e\u0440 \u00ab\u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u0435\u0439\u00bb: \u043f\u043e\u0440\u043e\u0433 sitelinks (\u043d\u0430\u043f\u0440. \u226520 \u0438\u043d\u0442\u0435\u0440\u0432\u0438\u043a) \u043f\u043b\u044e\u0441 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u043e\u0441\u043c\u043e\u0442\u0440\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u0441\u0442\u0430\u0442\u0435\u0439 (pageview-\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u0412\u0438\u043a\u0438\u043f\u0435\u0434\u0438\u0438) \u043a\u0430\u043a \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430 \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u0438. \u0410\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u0430 (Wikipedia-\u0438\u043d\u0444\u043e\u0431\u043e\u043a\u0441\u044b, IMDB) \u2014 \u0445\u0443\u0436\u0435: \u043d\u0435\u0442 \u0435\u0434\u0438\u043d\u043e\u0439 \u0434\u0430\u0442\u0438\u0440\u043e\u0432\u043a\u0438 \u0438 \u0430\u043b\u043b\u0438\u0430\u0441\u043e\u0432; \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u0435\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u043a\u0430\u043a \u043f\u0435\u0440\u0435\u043a\u0440\u0451\u0441\u0442\u043d\u0430\u044f \u0432\u0435\u0440\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438.\n\n**2) \u0421\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u0438 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u0441\u0442\u044c \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0439.**\n- \u041e\u0434\u0438\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043d\u0430\u0431\u043e\u0440 \u043f\u0430\u0440 \u0443\u0447\u0430\u0441\u0442\u0432\u0443\u0435\u0442 \u0432 \u043e\u0431\u043e\u0438\u0445 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u0445: \u0434\u043b\u044f \u043f\u0430\u0440\u044b (A=\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c, B=\u0440\u0435\u0431\u0451\u043d\u043e\u043a) \u0433\u0435\u043d\u0435\u0440\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043e\u0431\u0430 \u0437\u0430\u043f\u0440\u043e\u0441\u0430 \u2014 \u00ab\u041a\u0442\u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c B?\u00bb \u0438 \u00ab\u041a\u0442\u043e \u0440\u0435\u0431\u0451\u043d\u043e\u043a A?\u00bb. \u041d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f \u043f\u0430\u0440\u043d\u044b\u0435 \u043f\u043e \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044e.\n- \u0421\u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043e\u0442\u0431\u043e\u0440 \u043f\u043e \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438: \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u043c \u0438 \u043f\u0430\u0440\u044b, \u0433\u0434\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0435\u0435 \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u0438 \u0433\u0434\u0435 \u0440\u0435\u0431\u0451\u043d\u043e\u043a \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0435\u0435 (\u043f\u043e ratio pageviews), \u0447\u0442\u043e\u0431\u044b \u00ab\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0437\u0430\u043f\u0440\u043e\u0441\u0430\u00bb \u043d\u0435 \u0441\u043e\u0432\u043f\u0430\u0434\u0430\u043b\u043e \u0441 \u00ab\u043a\u0442\u043e \u0432 \u043f\u0430\u0440\u0435 \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u0435\u0435\u00bb. Stratify \u043f\u043e \u043a\u0432\u0430\u0440\u0442\u0438\u043b\u044f\u043c \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u0438.\n- \u0421\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u043f\u0440\u043e\u043c\u043f\u0442\u044b: \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u044b\u0435 \u0448\u0430\u0431\u043b\u043e\u043d\u044b \u043e\u0434\u043d\u043e\u0439 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u044b \u0438 \u0434\u043b\u0438\u043d\u044b, \u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 \u00abWho is the mother/father of {B}?\u00bb \u2194 \u00abWho is a child of {A}?\u00bb (\u0438\u043b\u0438 \u00abthe child\u00bb \u0432 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0433\u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0430). \u041c\u0438\u043d\u0438\u043c\u0443\u043c 2\u20133 \u0448\u0430\u0431\u043b\u043e\u043d\u0430 \u043d\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u2014 \u0448\u0430\u0431\u043b\u043e\u043d \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043c\u043e\u0434\u0435\u043b\u044c \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u043a\u0430\u043a \u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442; \u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u2014 \u0441\u0440\u0435\u0434\u043d\u0435\u0435 \u043f\u043e \u0448\u0430\u0431\u043b\u043e\u043d\u0430\u043c.\n- \u0418\u043c\u0435\u043d\u0430: \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u044b\u0439 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0444\u043e\u0440\u043c\u0430\u0442 (\u0438\u043c\u044f+\u0444\u0430\u043c\u0438\u043b\u0438\u044f, \u0431\u0435\u0437 \u0442\u0438\u0442\u0443\u043b\u043e\u0432); \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0434\u043b\u0438\u043d\u044b \u0438\u043c\u0435\u043d\u0438/\u0442\u043e\u043a\u0435\u043d\u0438\u0437\u0430\u0446\u0438\u0438; \u043f\u0440\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u043f\u0430\u0440\u043d\u044b\u0435 \u043f\u043e\u0434\u0431\u043e\u0440\u043a\u0438 \u0441 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u0438\u043c\u043e\u0439 \u0434\u043b\u0438\u043d\u043e\u0439 \u0438 \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u044c\u044e \u0438\u043c\u0451\u043d.\n\n**3) \u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u043e\u0442\u0432\u0435\u0442 \u0438 \u0430\u0432\u0442\u043e\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u043e\u0446\u0435\u043d\u043a\u0430.**\nGold-\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u0438\u0437 Wikidata: \u0434\u043b\u044f \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f R \u2014 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435\u0439 (\u043c\u0430\u0442\u044c+\u043e\u0442\u0435\u0446; \u0437\u0430\u043f\u0440\u043e\u0441 \u0443\u0442\u043e\u0447\u043d\u044f\u0435\u0442 \u043f\u043e\u043b, gold \u0441\u0443\u0436\u0430\u0435\u0442\u0441\u044f \u0434\u043e \u043e\u0434\u043d\u043e\u0433\u043e), \u0434\u043b\u044f P \u2014 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u0434\u0435\u0442\u0435\u0439 \u0441 P40. \u041e\u0446\u0435\u043d\u043a\u0430: \u043e\u0442\u0432\u0435\u0442 \u043c\u043e\u0434\u0435\u043b\u0438 \u2192 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f (NFKD, \u0441\u0442\u0440\u043e\u0447\u043d\u044b\u0435, \u0441\u043d\u044f\u0442\u0438\u0435 \u0434\u0438\u0430\u043a\u0440\u0438\u0442\u0438\u043a, \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0430\u0440\u0442\u0438\u043a\u043b\u0435\u0439/\u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u0432, \u0441\u043a\u043e\u0431\u043e\u043a) \u2192 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e\u043c \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0445 \u0441\u0442\u0440\u043e\u043a: \u043c\u0435\u0442\u043a\u0430 + aliases + \u0437\u0430\u0433\u043e\u043b\u043e\u0432\u043a\u0438 sitelinks \u043d\u0430 EN/\u0440\u043e\u0434\u043d\u043e\u043c \u044f\u0437\u044b\u043a\u0435, \u043f\u043b\u044e\u0441 \u043a\u0430\u043d\u043e\u043d\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043f\u0441\u0435\u0432\u0434\u043e\u043d\u0438\u043c\u044b (DJ, \u0443\u043c\u0435\u043d\u044c\u0448\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435) \u0438\u0437 alias-\u043c\u0430\u0441\u0441\u0438\u0432\u0430. Fuzzy-\u0434\u043e\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 (difflib ratio \u2265 0.9) \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0440\u0443\u0447\u043d\u043e\u0433\u043e \u0430\u0443\u0434\u0438\u0442\u0430 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u043e\u0439 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0438 (5\u201310%), \u0432 \u043e\u0441\u043d\u043e\u0432\u043d\u0443\u044e \u043c\u0435\u0442\u0440\u0438\u043a\u0443 \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442. \u041e\u0442\u0432\u0435\u0442 \u00abpartial name\u00bb (\u0442\u043e\u043b\u044c\u043a\u043e \u0438\u043c\u044f) \u0437\u0430\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043b\u0438\u0448\u044c \u043f\u0440\u0438 \u043e\u0434\u043d\u043e\u0437\u043d\u0430\u0447\u043d\u043e\u043c \u043f\u043e\u043f\u0430\u0434\u0430\u043d\u0438\u0438 \u0432 gold \u0431\u0435\u0437 \u043a\u043e\u043b\u043b\u0438\u0437\u0438\u0439 \u0432\u043d\u0443\u0442\u0440\u0438 \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u0430 \u043f\u0430\u0440\u044b. \u0414\u043b\u044f P \u043f\u0440\u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u0434\u0435\u0442\u044f\u0445: \u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u2014 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c (\u043f\u043e\u043f\u0430\u0434\u0430\u043d\u0438\u0435 \u0432 \u043b\u044e\u0431\u043e\u0435 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u043e\u0435 \u0438\u043c\u044f), \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u2014 set-F1 \u043f\u0440\u043e\u0442\u0438\u0432 \u043f\u043e\u043b\u043d\u043e\u0433\u043e \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 \u0434\u0435\u0442\u0435\u0439.\n\n**4) \u0421\u0440\u0430\u0432\u043d\u0438\u0432\u0430\u0435\u043c\u044b\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u044f.**\n- \u041e\u0441\u043d\u043e\u0432\u043d\u044b\u0435: R (\u0440\u0435\u0431\u0451\u043d\u043e\u043a\u2192\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c) vs P (\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u2192\u0440\u0435\u0431\u0451\u043d\u043e\u043a) \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435 \u043f\u0430\u0440.\n- \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u043d\u043e\u0441\u0442\u0438 (\u043d\u0435\u0439\u0442\u0440\u0430\u043b\u044c\u043d\u044b\u0435/\u00ab\u043e\u0431\u0440\u0430\u0442\u0438\u043c\u044b\u0435\u00bb \u043f\u0430\u0440\u044b): \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u043e\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u00ab\u0441\u0443\u043f\u0440\u0443\u0433(\u0430)\u00bb (P26) \u2014 \u0442\u0430\u043c, \u0433\u0434\u0435 \u043e\u0431\u0430 \u0441\u0443\u043f\u0440\u0443\u0433\u0430 \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u044b, \u043e\u0431\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u0440\u0430\u0432\u043d\u043e\u0441\u043b\u043e\u0436\u043d\u044b; \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0435 \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442, \u0447\u0442\u043e \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u043d\u0430 \u0434\u043b\u044f \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u043e\u0433\u043e \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f, \u0430 \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442\u043e\u043c \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0438.\n- \u0421\u0442\u0440\u0430\u0442\u044b \u043f\u043e \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0435: \u043f\u0430\u0440\u044b \u0441 \u0440\u043e\u0432\u043d\u043e \u043e\u0434\u043d\u0438\u043c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u043c \u0440\u0435\u0431\u0451\u043d\u043a\u043e\u043c vs \u0441 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u043c\u0438 (\u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437 \u0438 \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u00ab\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u00d7 \u0447\u0438\u0441\u043b\u043e \u0434\u0435\u0442\u0435\u0439\u00bb \u2014 \u043f\u0440\u044f\u043c\u043e \u0442\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442 \u0430\u043b\u044c\u0442\u0435\u0440\u043d\u0430\u0442\u0438\u0432\u043d\u043e\u0435 \u043e\u0431\u044a\u044f\u0441\u043d\u0435\u043d\u0438\u0435 \u00ab\u043e\u0434\u0438\u043d \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043f\u0440\u043e\u0442\u0438\u0432 \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 \u043c\u043d\u043e\u0433\u0438\u0445\u00bb).\n- \u0424\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0438: 2\u20133 \u043f\u0440\u043e\u043c\u043f\u0442-\u0448\u0430\u0431\u043b\u043e\u043d\u0430 \u043d\u0430 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435.\n- \u041c\u043e\u0434\u0435\u043b\u0438: \u22652 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430/\u0432\u0435\u0440\u0441\u0438\u0438 \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438 (\u043d\u0430\u043f\u0440\u0438\u043c\u0435\u0440 API-\u043c\u043e\u0434\u0435\u043b\u044c \u0438 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u0430\u044f open-weight), \u043f\u043b\u044e\u0441 \u0440\u0430\u0437\u043d\u044b\u0435 \u0440\u0430\u0437\u043c\u0435\u0440\u044b \u043e\u0434\u043d\u043e\u0433\u043e \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0430, \u0435\u0441\u043b\u0438 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u0431\u044e\u0434\u0436\u0435\u0442; \u043c\u043e\u0434\u0435\u043b\u044c \u2014 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u044d\u0444\u0444\u0435\u043a\u0442 \u0438\u043b\u0438 \u0444\u0430\u043a\u0442\u043e\u0440.\n- \u041f\u043b\u0435\u0439\u0446\u0435\u0431\u043e: \u0432\u044b\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435 \u0438\u043c\u0435\u043d\u0430 \u2014 \u0431\u0430\u0437\u043e\u0432\u044b\u0439 \u0443\u0440\u043e\u0432\u0435\u043d\u044c \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439/\u0444\u043e\u0440\u043c\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u044f \u043e\u0442\u0432\u0435\u0442\u043e\u0432.\n\n**5) \u041c\u0435\u0442\u0440\u0438\u043a\u0438 \u0438 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430.**\n- \u041f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f: \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c (0/1) \u043f\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u043c; \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 \u2014 \u0440\u0430\u0437\u043d\u0438\u0446\u0430 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0435\u0439 R\u2212P \u043d\u0430 \u043f\u0430\u0440\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435.\n- \u041f\u0430\u0440\u043d\u043e\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440: \u043a\u0440\u0438\u0442\u0435\u0440\u0438\u0439 \u041c\u0430\u043a\u041demar \u0434\u043b\u044f \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e\u0433\u043e \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442\u0430; \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e \u2014 \u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0440\u0435\u0433\u0440\u0435\u0441\u0441\u0438\u044f (correct ~ direction + template + log-freq + n_children + (1|pair/entity)) \u2014 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442 \u043f\u043e \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0438\u0437\u0430\u0446\u0438\u044e (\u043e\u0434\u0438\u043d \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0441 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u043c\u0438 \u0434\u0435\u0442\u044c\u043c\u0438 \u043f\u043e\u0440\u043e\u0436\u0434\u0430\u0435\u0442 \u0437\u0430\u0432\u0438\u0441\u0438\u043c\u044b\u0435 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f); \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u043d\u044b\u0439 \u0431\u0443\u0442\u0441\u0442\u0440\u0435\u043f\u0430 \u043f\u043e \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u044f\u043c \u043a\u0430\u043a \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c-\u0430\u043d\u0430\u043b\u0438\u0437.\n- \u0420\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430: Cohen's h \u0434\u043b\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u0434\u043e\u043b\u0435\u0439 + odds ratio \u0438\u0437 GLMM, \u0441 95% \u0414\u0418.\n- \u041c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f (\u0448\u0430\u0431\u043b\u043e\u043d\u044b \u00d7 \u043c\u043e\u0434\u0435\u043b\u0438 \u00d7 \u0441\u0442\u0440\u0430\u0442\u044b): Holm-Bonferroni \u043f\u043e \u043f\u0440\u0435\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c\u0443 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0443 \u043f\u0440\u043e\u0432\u0435\u0440\u043e\u043a; \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 \u043e\u0434\u0438\u043d \u0438 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430.\n- \u041e\u0431\u044a\u0451\u043c \u0432\u044b\u0431\u043e\u0440\u043a\u0438: \u0434\u043b\u044f \u043f\u0430\u0440\u043d\u043e\u0433\u043e \u0434\u0438\u0437\u0430\u0439\u043d\u0430 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u044f\u0435\u0442\u0441\u044f \u0434\u043e\u043b\u0435\u0439 \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u044b\u0445 \u043f\u0430\u0440; \u043f\u0440\u0438 \u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u043e\u0439 \u043e\u0446\u0435\u043d\u043a\u0435 \u0434\u043e\u043b\u0438 \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u0438 20\u201335% \u0438 \u0441\u0440\u0435\u0434\u043d\u0435\u0433\u043e \u044d\u0444\u0444\u0435\u043a\u0442\u0430 (\u0440\u0430\u0437\u043d\u0438\u0446\u0430 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0435\u0439 ~10\u201315 \u043f.\u043f.) N \u2248 250\u2013400 \u043f\u0430\u0440 \u0434\u0430\u0451\u0442 >80% \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 (\u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u0435\u0439 \u043d\u0430 stdlib \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430); \u0438\u0442\u043e\u0433\u043e\u0432\u044b\u0439 N \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043f\u043e\u0441\u043b\u0435 \u043f\u0438\u043b\u043e\u0442\u0430 \u043d\u0430 50 \u043f\u0430\u0440\u0430\u0445 (\u043f\u0438\u043b\u043e\u0442 \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u0438, \u043d\u0435 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b).\n- \u041d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044c \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u0438: temperature=0 \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u043e\u043d; \u043f\u043e\u0432\u0442\u043e\u0440 k=3 \u043f\u0440\u0438 T=0.7 \u043d\u0430 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435 \u2014 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u043e\u0442\u0432\u0435\u0442\u043e\u0432 \u0432\u0445\u043e\u0434\u0438\u0442 \u0432 \u043e\u0442\u0447\u0451\u0442; \u0414\u0418 \u0447\u0435\u0440\u0435\u0437 \u0431\u0443\u0442\u0441\u0442\u0440\u0435\u043f\u0430.\n\n**6) \u041a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u0432 \u0438\u0441\u043a\u0430\u0436\u0435\u043d\u0438\u044f.**\n- \u0427\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u044c/\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c \u0438\u043c\u0435\u043d\u0438: co-\u0432\u0430\u0440\u0438\u0430\u0442\u0430 pageviews, \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u043a\u0430\u0446\u0438\u044f, \u0431\u0430\u043b\u0430\u043d\u0441\u0438\u0440\u043e\u0432\u043a\u0430 \u00ab\u043a\u0442\u043e \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0435\u0435 \u0432 \u043f\u0430\u0440\u0435\u00bb (\u0441\u043c. \u043f.2).\n- \u041f\u043e\u0437\u0438\u0446\u0438\u044f/\u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u0442\u0435\u043a\u0441\u0442\u0430 \u0432 \u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0438\u0445 \u0434\u0430\u043d\u043d\u044b\u0445: \u0442\u0438\u043f\u0438\u0447\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 \u00abX \u2014 \u0441\u044b\u043d \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0433\u043e Y\u00bb \u0434\u0435\u043b\u0430\u0435\u0442 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u043b\u0435\u0433\u043a\u043e \u0432\u044b\u0432\u043e\u0434\u0438\u043c\u044b\u043c \u0438\u0437 \u0441\u0442\u0430\u0442\u044c\u0438 \u043e \u0440\u0435\u0431\u0451\u043d\u043a\u0435, \u0442\u043e\u0433\u0434\u0430 \u043a\u0430\u043a \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 \u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0435 \u0434\u0435\u0442\u0438 \u043c\u043e\u0433\u0443\u0442 \u043d\u0435 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u0442\u044c\u0441\u044f; \u044d\u0442\u043e \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u044b, \u043d\u043e \u0447\u0442\u043e\u0431\u044b \u043e\u0442\u0434\u0435\u043b\u0438\u0442\u044c \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043c\u043e\u0434\u0435\u043b\u0438\u00bb \u043e\u0442 \u00ab\u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0438 \u043a\u043e\u0440\u043f\u0443\u0441\u0430\u00bb, \u0432 \u043e\u0442\u0447\u0451\u0442 \u0432\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u0438\u0437\u043c\u0435\u0440\u0438\u043c\u0430\u044f \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u0430: \u0447\u0430\u0441\u0442\u043e\u0442\u0430 \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u043c\u043e\u0441\u0442\u0438 \u0438\u043c\u0451\u043d \u0438 \u043f\u043e\u0440\u044f\u0434\u043e\u043a \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u044f (\u043f\u043e \u0442\u0435\u043a\u0441\u0442\u0443 \u0441\u0442\u0430\u0442\u0435\u0439), \u0432\u043a\u043b\u044e\u0447\u0430\u0435\u043c\u0430\u044f \u0432 GLMM.\n- \u0420\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u0430\u044f \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u044c (\u043e\u0434\u0438\u043d \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u043f\u0440\u043e\u0442\u0438\u0432 \u043e\u0434\u043d\u043e\u0433\u043e \u0438\u0437 N \u0434\u0435\u0442\u0435\u0439): \u0441\u0442\u0440\u0430\u0442\u044b \u043f\u043e N \u0434\u0435\u0442\u0435\u0439 + \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u043e\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u00ab\u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb + set-F1; \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u00d7N \u0432 \u043c\u043e\u0434\u0435\u043b\u0438.\n- \u0424\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 \u043f\u0440\u043e\u043c\u043f\u0442\u0430: \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432, \u0444\u0430\u043a\u0442\u043e\u0440 \u0432 \u043c\u043e\u0434\u0435\u043b\u0438; \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u0443\u0441\u0440\u0435\u0434\u043d\u0435\u043d\u0430 \u043f\u043e \u0448\u0430\u0431\u043b\u043e\u043d\u0430\u043c.\n- \u0421\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c: \u0441\u043c. \u043f.5.\n- \u0414\u0430\u0442\u0430 \u0441\u0440\u0435\u0437\u0430 \u0437\u043d\u0430\u043d\u0438\u0439: \u0431\u0435\u0440\u0451\u043c \u0442\u043e\u043b\u044c\u043a\u043e \u043f\u0430\u0440\u044b, \u0441\u0443\u0449\u0435\u0441\u0442\u0432\u043e\u0432\u0430\u0432\u0448\u0438\u0435 \u0432 Wikidata-\u0434\u0430\u043c\u043f\u0435, \u0434\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0440\u0430\u043d\u044c\u0448\u0435 cutoff \u043a\u0430\u0436\u0434\u043e\u0439 \u043c\u043e\u0434\u0435\u043b\u0438 (\u0434\u0435\u0442\u0438, \u0440\u043e\u0436\u0434\u0451\u043d\u043d\u044b\u0435/\u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f, \u0441\u0442\u0430\u0432\u0448\u0438\u0435 \u043f\u0443\u0431\u043b\u0438\u0447\u043d\u044b\u043c\u0438 \u043f\u043e\u0437\u0436\u0435 cutoff \u2014 \u0438\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f; \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043f\u043e\u0432\u0442\u043e\u0440 \u0430\u043d\u0430\u043b\u0438\u0437\u0430 \u043d\u0430 \u0441\u0442\u0440\u043e\u0433\u043e\u043c \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435 \u00ab\u0444\u0430\u043a\u0442 \u0441\u0442\u0430\u0440\u0448\u0435 cutoff \u043d\u0430 \u22652 \u0433\u043e\u0434\u0430\u00bb).\n\n## \u0414\u041e\u041f\u0423\u0429\u0415\u041d\u0418\u042f\n\n1. \u0426\u0435\u043b\u0435\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c(\u0438) \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b \u043f\u043e\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u043e\u0439; \u0434\u043e\u043f\u0443\u0441\u043a\u0430\u0435\u043c \u043b\u044e\u0431\u043e\u0439 \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0442\u0438\u0432\u043d\u044b\u0439 LLM, \u0438 \u0447\u0442\u043e \u043f\u043b\u0430\u043d \u0434\u043e\u043b\u0436\u0435\u043d \u0440\u0430\u0431\u043e\u0442\u0430\u0442\u044c \u0434\u043b\u044f \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u043a\u0430\u043a \u0444\u0430\u043a\u0442\u043e\u0440.\n2. Wikidata \u043f\u0440\u0438\u043d\u0438\u043c\u0430\u0435\u0442\u0441\u044f \u043f\u0440\u0438\u0435\u043c\u043b\u0435\u043c\u044b\u043c \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a\u043e\u043c \u0438\u0441\u0442\u0438\u043d\u044b \u0434\u043b\u044f \u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0445 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439 \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u0435\u0439 \u043f\u0440\u0438 \u0434\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u043c \u0441\u043d\u0438\u043c\u043a\u0435 \u0438 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0435 \u043f\u043e\u0440\u043e\u0433\u043e\u043c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438.\n3. \u0414\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u0430 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0430 \u0434\u0430\u043d\u043d\u044b\u0445 \u043e\u0444\u043b\u0430\u0439\u043d-\u0444\u0430\u0439\u043b\u043e\u043c (CSV \u043f\u0430\u0440 + \u043c\u0435\u0442\u0430\u0434\u0430\u043d\u043d\u044b\u0435) \u0432 \u043e\u0431\u0445\u043e\u0434 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0435\u0439 \u0441\u0435\u0442\u0438.\n4. \u00ab\u041f\u0440\u0430\u0432\u0438\u043b\u044c\u043d\u044b\u0439 \u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb \u043f\u0440\u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u0434\u0435\u0442\u044f\u0445 = \u043b\u044e\u0431\u043e\u0439 \u0438\u0437 \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430 (\u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430); \u043f\u043e\u043b\u043d\u0430\u044f \u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u044c \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0439 \u0430\u043d\u0430\u043b\u0438\u0437.\n5. \u042f\u0437\u044b\u043a\u043e\u0432\u043e\u0439 \u0444\u043e\u043a\u0443\u0441 \u2014 \u0440\u0443\u0441\u0441\u043a\u0438\u0435/\u0430\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u0438\u0435 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0438 \u043d\u0435 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0435\u043c: \u043e\u0441\u043d\u043e\u0432\u043d\u0430\u044f \u0441\u0435\u0442\u043a\u0430 \u043d\u0430 \u0430\u043d\u0433\u043b\u0438\u0439\u0441\u043a\u043e\u043c, \u0438\u043c\u0435\u043d\u0430 \u0432 \u043b\u0430\u0442\u0438\u043d\u0441\u043a\u043e\u0439 \u0442\u0440\u0430\u043d\u0441\u043b\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0438; \u043d\u0435-\u043b\u0430\u0442\u0438\u043d\u0441\u043a\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 \u2014 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c-\u0431\u043b\u043e\u043a.\n\n## \u041d\u0415\u041e\u041f\u0420\u0415\u0414\u0401\u041b\u0415\u041d\u041d\u041e\u0421\u0422\u0418\n\n1. \u0426\u0435\u043b\u0435\u0432\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438, \u0438\u0445 \u0447\u0438\u0441\u043b\u043e, \u0432\u0435\u0440\u0441\u0438\u0438, cutoff \u0437\u043d\u0430\u043d\u0438\u0439 \u0438 \u0431\u044e\u0434\u0436\u0435\u0442 \u0432\u044b\u0447\u0438\u0441\u043b\u0435\u043d\u0438\u0439 \u2014 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b; \u0432\u043b\u0438\u044f\u044e\u0442 \u043d\u0430 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u043f\u043e \u0434\u0430\u0442\u0435 \u0438 \u043d\u0430 \u0447\u0438\u0441\u043b\u043e \u0444\u0430\u043a\u0442\u043e\u0440\u043e\u0432.\n2. \u0414\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u0439 N \u0438 \u0431\u044e\u0434\u0436\u0435\u0442 (API-\u0442\u043e\u043a\u0435\u043d\u044b vs CPU-\u0447\u0430\u0441\u044b) \u2014 \u043d\u0435 \u0437\u0430\u0434\u0430\u043d\u044b; \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u044f \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u0443\u0442\u043e\u0447\u043d\u0438\u0442 \u0442\u0440\u0435\u0431\u0443\u0435\u043c\u044b\u0439 N.\n3. \u041f\u0440\u0438\u0451\u043c\u043d\u044b\u0435/\u0443\u0441\u044b\u043d\u043e\u0432\u043b\u0451\u043d\u043d\u044b\u0435/\u043d\u0435\u0440\u043e\u0434\u043d\u044b\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f: Wikidata P6/P7/P40 \u0438\u0445 \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0435\u0442; \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u0438\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f/\u0432\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u044f \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u0440\u0435\u0448\u0435\u043d\u0438\u044f \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u0442\u0435\u043b\u044f (\u0432\u043b\u0438\u044f\u0435\u0442 \u043d\u0430 gold-\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0430).\n4. \u042d\u043c\u043f\u0438\u0440\u0438\u0447\u0435\u0441\u043a\u0438\u0439 \u0438\u0441\u0445\u043e\u0434 \u043d\u0435\u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d: \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430\u044f \u00ab\u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f\u00bb \u043c\u043e\u0436\u0435\u0442 \u043e\u0431\u044a\u044f\u0441\u043d\u044f\u0442\u044c\u0441\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043e\u0439 \u043a\u043e\u0440\u043f\u0443\u0441\u0430 (\u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c), \u0430 \u043d\u0435 \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435\u043c\u00bb \u043c\u043e\u0434\u0435\u043b\u0438 \u2014 \u0434\u0438\u0437\u0430\u0439\u043d \u044d\u0442\u043e \u0440\u0430\u0437\u0434\u0435\u043b\u044f\u0435\u0442, \u043d\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0430 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u043d\u0435 \u0438\u0437\u0432\u0435\u0441\u0442\u0435\u043d.\n5. \u041f\u043e\u043b\u043d\u043e\u0442\u0430/\u0441\u0432\u0435\u0436\u0435\u0441\u0442\u044c Wikidata \u043f\u043e \u043d\u0435-\u0437\u0430\u043f\u0430\u0434\u043d\u044b\u043c \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u044f\u043c; \u043f\u043e\u0442\u0435\u043d\u0446\u0438\u0430\u043b\u044c\u043d\u043e\u0435 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043f\u043e\u043a\u0440\u044b\u0442\u0438\u0435-\u0438\u0441\u043a\u0430\u0436\u0435\u043d\u0438\u0435.\n6. \u0424\u043e\u0440\u043c\u0430\u0442 \u043f\u043e\u0434\u0430\u0447\u0438 \u043e\u0442\u0432\u0435\u0442\u0430 \u043c\u043e\u0434\u0435\u043b\u0438 (\u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0439 \u0442\u0435\u043a\u0441\u0442 vs structured) \u0437\u0430\u0432\u0438\u0441\u0438\u0442 \u043e\u0442 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439; \u0441\u043a\u043e\u0440\u0438\u043d\u0433 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e\u0433\u043e \u0442\u0435\u043a\u0441\u0442\u0430 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u0430\u0440\u0441\u0435\u0440\u0430 \u0438\u043c\u0451\u043d.\n\n\u0418\u0442\u043e\u0433\u043e\u0432\u044b\u0439 \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442 \u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u044f\u043b\u0441\u044f \u0438 \u043d\u0435 \u043e\u043f\u0438\u0441\u044b\u0432\u0430\u0435\u0442\u0441\u044f; \u043f\u0438\u043b\u043e\u0442\u043d\u044b\u0445 \u0437\u0430\u043f\u0443\u0441\u043a\u043e\u0432 \u043d\u0435 \u0431\u044b\u043b\u043e.", "evidence": "\u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f: (1) `ls -laR /workspace` \u2014 \u0442\u043e\u043b\u044c\u043a\u043e task.json (537 \u0431\u0430\u0439\u0442); \u0442\u0440\u0435\u043a: \u00abDesign-only task; repositories and compute are not required\u00bb. (2) \u0421\u0435\u0442\u0435\u0432\u043e\u0439 \u0442\u0435\u0441\u0442: socket.create_connection(('8.8.8.8',53)) \u2192 OSError \u00abNetwork is unreachable\u00bb \u2014 \u0441\u0435\u0442\u044c \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u043d\u0435\u0434\u043e\u0441\u0442\u0443\u043f\u043d\u0430; pip \u0435\u0441\u0442\u044c, \u043d\u043e \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043d\u0435\u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430. (3) python3 3.14.4; \u0438\u043c\u043f\u043e\u0440\u0442 torch/transformers/scipy/numpy/pandas/statsmodels \u2192 ImportError; stdlib (sqlite3, json, statistics, random, difflib, unicodedata) \u0440\u0430\u0431\u043e\u0442\u0430\u0435\u0442 \u2014 \u00abstdlib ok\u00bb. (4) `pip3 list | grep -iE 'numpy|scipy|torch|transform|pandas|sklearn|scikit|hugging|llama'` \u2014 \u043f\u0443\u0441\u0442\u043e (\u0442\u043e\u043b\u044c\u043a\u043e requests \u0431\u0435\u0437 \u0441\u0435\u0442\u0438 \u0431\u0435\u0441\u043f\u043e\u043b\u0435\u0437\u0435\u043d). (5) ~/.cache, /data, /models \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442; find \u043f\u043e *.gguf/wikidata* \u2014 \u043f\u0443\u0441\u0442\u043e: \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u0438 \u0434\u0430\u043c\u043f\u043e\u0432 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u043e \u043d\u0435\u0442. (6) \u0420\u0435\u0441\u0443\u0440\u0441\u044b: nproc=224, RAM 2011 \u0413\u0411, 39 \u0413\u0411 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u043e \u043d\u0430 \u0440\u0430\u0437\u0434\u0435\u043b\u0435; GPU \u043e\u0442\u043a\u043b\u044e\u0447\u0451\u043d \u0441\u043e\u0433\u043b\u0430\u0441\u043d\u043e environment. \u0412\u044b\u0432\u043e\u0434: \u0432 \u0442\u0435\u043a\u0443\u0449\u0435\u043c \u0431\u043e\u043a\u0441\u0435 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u043e \u043b\u0438\u0448\u044c \u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u0438\u0435 \u0438 pure-python \u0437\u0430\u0433\u043e\u0442\u043e\u0432\u043a\u0438; \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0435 \u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0434\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0433\u043e Wikidata-\u0441\u043b\u0435\u043f\u043a\u0430 \u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u0430 \u043a \u043c\u043e\u0434\u0435\u043b\u044f\u043c (API \u0438\u043b\u0438 \u0432\u0435\u0441\u0430).", "assumptions": ["\u0426\u0435\u043b\u0435\u0432\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0435 \u0437\u0430\u0434\u