u0431\u0451\u043d\u043e\u043a\u00bb \u043e \u0440\u0435\u0430\u043b\u044c\u043d\u044b\u0445 \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u044f\u0445 LLM \u0442\u043e\u0447\u043d\u0435\u0435 \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u0440\u0435\u0431\u0451\u043d\u043a\u0430, \u0447\u0435\u043c \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u043f\u043e \u0438\u043c\u0435\u043d\u0438 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f.\n\n**\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 (\u043f\u0440\u0435\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f):** \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u044b\u0439 (one-sided) \u0442\u0435\u0441\u0442 \u041c\u0430\u043a\u041demar \u043d\u0430 \u043f\u0430\u0440\u043d\u044b\u0445 \u0431\u0438\u043d\u0430\u0440\u043d\u044b\u0445 \u0438\u0441\u0445\u043e\u0434\u0430\u0445 \u00ab\u0432\u0435\u0440\u043d\u043e/\u043d\u0435\u0432\u0435\u0440\u043d\u043e\u00bb \u0434\u043b\u044f \u043e\u0434\u043d\u043e\u0433\u043e \u0438 \u0442\u043e\u0433\u043e \u0436\u0435 \u043d\u0430\u0431\u043e\u0440\u0430 \u043f\u0430\u0440:\n- H0: \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c(\u0440\u0435\u0431\u0451\u043d\u043e\u043a\u2192\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c) \u2264 \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c(\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u2192\u0440\u0435\u0431\u0451\u043d\u043e\u043a); H1: \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c(R\u2192P) > \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c(P\u2192R). \u03b1 = 0,05 (\u043e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439), \u0435\u0434\u0438\u043d\u0438\u0447\u043d\u044b\u0439 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442, \u043e\u0434\u043d\u0430 \u043c\u043e\u0434\u0435\u043b\u044c-\u00ab\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441\u00bb (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430; \u0435\u0441\u043b\u0438 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u043e \u2014 \u0431\u0435\u0440\u0451\u0442\u0441\u044f \u043f\u0440\u0435\u0434\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u0430\u044f \u0433\u043b\u0430\u0432\u043d\u0430\u044f, \u043e\u0441\u0442\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u0445\u043e\u0434\u044f\u0442 \u0432\u043e \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438).\n- \u0415\u0434\u0438\u043d\u0438\u0446\u0430 \u043d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f \u2014 \u043f\u0430\u0440\u0430 (\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c, \u0440\u0435\u0431\u0451\u043d\u043e\u043a); \u0432 \u043e\u0431\u043e\u0438\u0445 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u0445 \u043f\u0430\u0440\u0430 \u043e\u0434\u043d\u0430 \u0438 \u0442\u0430 \u0436\u0435.\n\n## 2. \u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a \u0434\u0430\u043d\u043d\u044b\u0445, \u043e\u0442\u0431\u043e\u0440, \u0441\u0440\u0435\u0437 \u0437\u043d\u0430\u043d\u0438\u0439\n\n**\u0418\u0441\u0442\u043e\u0447\u043d\u0438\u043a:** \u0434\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u043f\u043e\u043b\u043d\u044b\u0439 \u0434\u0430\u043c\u043f Wikidata (\u0435\u0434\u0438\u043d\u044b\u0439 \u0441\u043d\u0438\u043c\u043e\u043a, \u0434\u0430\u0442\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f). \u0421\u0432\u043e\u0439\u0441\u0442\u0432\u0430: **P22 (\u043e\u0442\u0435\u0446), P25 (\u043c\u0430\u0442\u044c), P40 (\u0440\u0435\u0431\u0451\u043d\u043e\u043a)** \u2014 \u0432 \u0447\u0435\u0440\u043d\u043e\u0432\u043e\u043c \u043f\u043b\u0430\u043d\u0435 \u044f \u043e\u043f\u0438\u0441\u0430\u0442\u0435\u043b\u044c\u043d\u043e \u0443\u043a\u0430\u0437\u0430\u043b \u00abP6/P7\u00bb; \u0438\u0441\u043f\u0440\u0430\u0432\u043b\u044f\u044e \u043d\u0430 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u043d\u044b\u0435 P22/P25 (\u0432 \u0444\u0438\u043d\u0430\u043b\u044c\u043d\u043e\u043c \u043a\u043e\u0434\u0435 \u0438\u0441\u043f\u043e\u043b\u044c\u0437\u0443\u044e\u0442\u0441\u044f \u043e\u043d\u0438). \u0420\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f: R-\u0437\u0430\u043f\u0440\u043e\u0441 \u2014 \u00ab\u043c\u0430\u0442\u044c/\u043e\u0442\u0435\u0446 {\u0440\u0435\u0431\u0451\u043d\u043a\u0430}\u00bb \u0441 \u043f\u043e\u043b\u043e\u043c \u0438\u0437 P21, gold \u2014 \u0441\u043e\u043e\u0442\u0432\u0435\u0442\u0441\u0442\u0432\u0443\u044e\u0449\u0438\u0439 P25/P22; P-\u0437\u0430\u043f\u0440\u043e\u0441 \u2014 \u00ab\u0440\u0435\u0431\u0451\u043d\u043e\u043a {\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f}\u00bb, gold \u2014 \u0432\u0441\u0435 P40, \u0443 \u043a\u043e\u0442\u043e\u0440\u044b\u0445 \u0434\u0430\u043d\u043d\u044b\u0439 entity \u0441\u0442\u043e\u0438\u0442 \u0432 P22/P25 (\u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u044c \u043e\u0431\u0440\u0430\u0442\u043d\u044b\u0445 \u0441\u0432\u044f\u0437\u0435\u0439 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u0430).\n\n**\u041a\u0440\u0438\u0442\u0435\u0440\u0438\u0438 \u043e\u0442\u0431\u043e\u0440\u0430 \u043f\u0430\u0440 (\u0432\u0441\u0435 \u2014 \u0438\u0437 \u0442\u043e\u0433\u043e \u0436\u0435 \u0441\u043d\u0438\u043c\u043a\u0430, \u043e\u0444\u043b\u0430\u0439\u043d-\u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u043e):**\n1. \u0417\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u044c: \u0443 \u00ab\u0437\u0430\u043f\u0440\u0430\u0448\u0438\u0432\u0430\u0435\u043c\u043e\u0439\u00bb \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438 \u226520 sitelinks; \u0443 \u0432\u0442\u043e\u0440\u043e\u0439 \u2014 \u22655 (\u043f\u043e\u0440\u043e\u0433\u0438 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430, \u0432\u0430\u0440\u044c\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u0447\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438).\n2. \u041d\u0435 \u0441\u043b\u0443\u0436\u0435\u0431\u043d\u044b\u0435 \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438 (\u043d\u0435\u0442 Q-\u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432, \u0442\u043e\u043b\u044c\u043a\u043eHumans, \u0434\u0430\u0442\u0430 \u0441\u043c\u0435\u0440\u0442\u0438/\u0440\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u0437\u0430\u043f\u043e\u043b\u043d\u0435\u043d\u044b).\n3. \u0418\u0441\u043a\u043b\u044e\u0447\u0435\u043d\u0438\u0435 \u043f\u0430\u0440 \u0441 \u0444\u043b\u0430\u0433\u0430\u043c\u0438 \u00ab\u0441\u043f\u043e\u0440\u043d\u043e\u0441\u0442\u044c\u00bb (\u043e\u0431\u0441\u0443\u0436\u0434\u0435\u043d\u0438\u0435 P22 \u0432 \u0440\u0430\u043d\u0433\u0430\u0445 deprecated/preferred \u043d\u0435-\u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439).\n4. **\u0411\u0430\u043b\u0430\u043d\u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438:** \u043d\u0430\u0431\u043e\u0440 \u0444\u043e\u0440\u043c\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0438\u0437 \u0434\u0432\u0443\u0445 \u043f\u043b\u0451\u043d \u2014 \u00ab\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0435\u0435 \u0440\u0435\u0431\u0451\u043d\u043a\u0430\u00bb \u0438 \u00ab\u0440\u0435\u0431\u0451\u043d\u043e\u043a \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u0435\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f\u00bb (\u043f\u043e \u0447\u0438\u0441\u043b\u0443 sitelinks \u043a\u0430\u043a \u043f\u0440\u043e\u043a\u0441\u0438; pageview-\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u2014 \u043e\u043f\u0446\u0438\u043e\u043d\u0430\u043b\u044c\u043d\u043e\u0435 \u0443\u0441\u043b\u043e\u0432\u043d\u043e\u0435 \u0440\u0430\u0441\u0448\u0438\u0440\u0435\u043d\u0438\u0435, \u043f.5), \u043f\u043e 50/50.\n5. \u0421\u0442\u0440\u0430\u0442\u044b: 1 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0439 \u0440\u0435\u0431\u0451\u043d\u043e\u043a vs \u22652 (\u043f\u043e P40), \u043f\u0440\u043e\u043f\u043e\u0440\u0446\u0438\u044f 50/50.\n\n**\u041f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u0441\u0440\u0435\u0437\u0430 \u0437\u043d\u0430\u043d\u0438\u0439:** \u0446\u0435\u043b\u0435\u0432\u0430\u044f \u0434\u0430\u0442\u0430 T\u2080 = \u043c\u0438\u043d\u0438\u043c\u0443\u043c \u0438\u0437 cutoff \u0432\u0441\u0435\u0445 \u0437\u0430\u0434\u0435\u0439\u0441\u0442\u0432\u043e\u0432\u0430\u043d\u043d\u044b\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439, \u043c\u0438\u043d\u0443\u0441 \u0431\u0443\u0444\u0435\u0440 24 \u043c\u0435\u0441\u044f\u0446\u0430. \u0418\u0441\u043a\u043b\u044e\u0447\u0430\u044e\u0442\u0441\u044f \u043f\u0430\u0440\u044b, \u0433\u0434\u0435 \u0444\u0430\u043a\u0442 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u043f\u043e\u044f\u0432\u0438\u043b\u0441\u044f \u0432 \u0441\u043d\u0438\u043c\u043a\u0435 \u043f\u043e\u0437\u0436\u0435 T\u2080 (\u043f\u043e revision-\u043c\u0435\u0442\u0430\u0434\u0430\u043d\u043d\u044b\u043c \u0443\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u0438\u044f, \u0435\u0441\u043b\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u044b) \u0438\u043b\u0438 \u0440\u0435\u0431\u0451\u043d\u043e\u043a \u0440\u043e\u0434\u0438\u043b\u0441\u044f \u043f\u043e\u0437\u0436\u0435 T\u2080. \u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043f\u043e\u0432\u0442\u043e\u0440 \u043d\u0430 \u0441\u0442\u0440\u043e\u0433\u043e\u043c \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435 (\u0431\u0443\u0444\u0435\u0440 24 \u043c\u0435\u0441.) \u043f\u0440\u043e\u0442\u0438\u0432 \u00ab\u0432\u0441\u0451 \u0432 \u0441\u043d\u0438\u043c\u043a\u0435\u00bb \u2014 \u0441 \u044f\u0432\u043d\u043e\u0439 \u043f\u043e\u043c\u0435\u0442\u043a\u043e\u0439, \u0447\u0442\u043e \u0441\u043d\u0438\u043c\u043e\u043a \u0441\u0442\u0430\u0440\u0448\u0435 cutoff \u043d\u0435 \u0433\u0430\u0440\u0430\u043d\u0442\u0438\u0440\u0443\u0435\u0442 \u00ab\u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0443\u044e\u00bb \u0434\u0430\u0432\u043d\u043e\u0441\u0442\u044c \u0444\u0430\u043a\u0442\u0430.\n\n## 3. \u0421\u0442\u0438\u043c\u0443\u043b\u044b \u0438 \u043f\u0440\u043e\u043c\u043f\u0442-\u0448\u0430\u0431\u043b\u043e\u043d\u044b\n\n\u0418\u043c\u044f \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438 \u0432 \u043f\u0440\u043e\u043c\u043f\u0442\u0435 \u2014 \u043c\u0435\u0442\u043a\u0430 EN-\u043b\u0435\u0439\u0431\u043b \u0441\u043d\u0438\u043c\u043a\u0430, \u043f\u0440\u0438 \u043a\u043e\u043b\u043b\u0438\u0437\u0438\u044f\u0445 \u2014 \u043c\u0435\u0442\u043a\u0430 + \u0443\u0442\u043e\u0447\u043d\u0438\u0442\u0435\u043b\u044c \u0438\u0437 \u0441\u043a\u043e\u0431\u043e\u043a \u043b\u0435\u0439\u0431\u043b\u0430 (\u00abMichael Jordan (basketball)\u00bb \u2192 \u00abMichael Jordan\u00bb, \u0443\u0442\u043e\u0447\u043d\u0438\u0442\u0435\u043b\u044c \u0432 gold-\u0430\u043b\u0438\u0430\u0441\u044b).\n\n\u0422\u0440\u0438 \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u044b\u0445 \u0448\u0430\u0431\u043b\u043e\u043d\u0430 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e\u0441\u043b\u043e\u0432\u043d\u043e \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430):\n- **R:** \u00abWho is the {mother|father} of {CHILD}? Answer with the full name only.\u00bb / \u00abName the {mother|father} of {CHILD}. One name.\u00bb / \u00abThe {mother|father} of {CHILD} is a famous person. Who is it?\u00bb\n- **P:** \u00abWho is a child of {PARENT}? Answer with the full name only.\u00bb / \u00abName a child of {PARENT}. One name.\u00bb / \u00abA child of {PARENT} is a famous person. Who is it?\u00bb\n\n\u041e\u0431\u043e\u0441\u043d\u043e\u0432\u0430\u043d\u0438\u0435 \u043f\u0430\u0440\u0430\u043b\u043b\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u0438: \u0438\u0434\u0435\u043d\u0442\u0438\u0447\u043d\u0430\u044f \u0441\u0438\u043d\u0442\u0430\u043a\u0441\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u00ab\u043f\u0430\u0440\u043d\u044b\u0445\u00bb \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432 1:1, \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u0434\u043b\u0438\u043d\u0430 (\u00b13 \u0441\u043b\u043e\u0432\u0430), \u043e\u0434\u0438\u043d\u0430\u043a\u043e\u0432\u0430\u044f \u0438\u043d\u0441\u0442\u0440\u0443\u043a\u0446\u0438\u044f \u0444\u043e\u0440\u043c\u0430\u0442\u0430 \u043e\u0442\u0432\u0435\u0442\u0430; \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0435 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u0435 \u2014 \u0440\u043e\u043b\u044c \u0438\u043c\u0435\u043d\u0438 \u0432 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u0438. \u00aba child\u00bb (\u043d\u0435 \u00abthe child\u00bb) \u2014 \u0447\u0442\u043e\u0431\u044b \u043d\u0435 \u0432\u044b\u0434\u0430\u0432\u0430\u0442\u044c \u0438\u043d\u0444\u043e\u0440\u043c\u0430\u0446\u0438\u044e \u043e\u0431 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u043e\u0441\u0442\u0438; \u0434\u043b\u044f \u0441\u0442\u0440\u0430\u0442\u044b \u00ab\u043e\u0434\u0438\u043d \u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u044f\u0435\u0442\u0441\u044f \u00abthe child\u00bb (\u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u00ab\u0430\u0440\u0442\u0435\u0444\u0430\u043a\u0442 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0433\u043e \u0430\u0440\u0442\u0438\u043a\u043b\u044f\u00bb). \u041f\u043e\u0440\u044f\u0434\u043e\u043a \u043f\u0430\u0440 \u0438 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0439 \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0438\u0440\u0443\u0435\u0442\u0441\u044f (seed \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f); \u043c\u0435\u0436\u0434\u0443 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u043c\u0438 \u2014 washout-\u043f\u0435\u0440\u0435\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0434\u043b\u044f \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044f \u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442\u043d\u044b\u0445 \u044d\u0444\u0444\u0435\u043a\u0442\u043e\u0432 (\u043a\u0430\u0436\u0434\u044b\u0439 \u043f\u0440\u043e\u043c\u043f\u0442 \u2014 \u0441\u0432\u0435\u0436\u0430\u044f \u0441\u0435\u0441\u0441\u0438\u044f \u0431\u0435\u0437 \u0438\u0441\u0442\u043e\u0440\u0438\u0438; \u044d\u0442\u043e \u0436\u0435 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0435).\n\n## 4. \u041f\u0440\u043e\u0442\u043e\u043a\u043e\u043b \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u043d\u0438\u044f\n\n**\u041d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f (stdlib):** NFKD \u2192 \u0443\u0434\u0430\u043b\u0435\u043d\u0438\u0435 \u0434\u0438\u0430\u043a\u0440\u0438\u0442\u0438\u043a\u0438 \u2192 \u043d\u0438\u0436\u043d\u0438\u0439 \u0440\u0435\u0433\u0438\u0441\u0442\u0440 \u2192 removal \u043f\u0443\u043d\u043a\u0442\u0443\u0430\u0446\u0438\u0438/\u043a\u0430\u0432\u044b\u0447\u0435\u043a/\u043f\u0440\u0435\u0444\u0438\u043a\u0441\u043e\u0432 (van, de, der, \u0444\u043e\u043d; \u0442\u0438\u0442\u0443\u043b\u043e\u0432 Sir, Dr) \u2192 \u0441\u0445\u043b\u043e\u043f\u044b\u0432\u0430\u043d\u0438\u0435 \u043f\u0440\u043e\u0431\u0435\u043b\u043e\u0432. **\u0414\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u043e** (\u043f\u043e \u0438\u0442\u043e\u0433\u0430\u043c \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u0438, \u043f.8): \u0442\u0430\u0431\u043b\u0438\u0446\u0430 \u0440\u0443\u0447\u043d\u043e\u0439 \u0442\u0440\u0430\u043d\u0441\u043b\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u0438 \u0434\u043b\u044f \u043d\u0435-NFKD-\u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432 (\u00f0, \u00f8, \u00e6, \u0142\u2026), \u0442.\u043a. \u043e\u0434\u043d\u043e\u0439 \u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u0438 \u043d\u0435\u0434\u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e.\n\n**\u0421\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435:** \u043e\u0442\u0432\u0435\u0442 \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u0441 gold-\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e\u043c \u0441\u0442\u0440\u043e\u043a = {EN-\u043b\u0435\u0439\u0431\u043b + \u0432\u0441\u0435 aliases + \u043b\u0435\u043a\u0435\u043c\u044b (\u043f\u0435\u0440\u0432\u043e\u0435+\u043f\u043e\u0441\u043b\u0435\u0434\u043d\u0435\u0435 \u0441\u043b\u043e\u0432\u043e) + \u043b\u0435\u0439\u0431\u043b\u044b \u043d\u0430 \u044f\u0437\u044b\u043a\u0430\u0445 \u0438\u0437 \u043c\u0435\u0442\u043a\u0438 \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438} \u0434\u043b\u044f \u043a\u0430\u0436\u0434\u043e\u0433\u043e \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u043e\u0433\u043e \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f/\u0440\u0435\u0431\u0451\u043d\u043a\u0430. \u0421\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0435 \u2014 \u0442\u043e\u0447\u043d\u043e\u0435 \u043f\u043e\u0441\u043b\u0435 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u0438\u043b\u0438 \u0434\u0432\u0443\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0435\u0435 \u0432\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u0435 \u043b\u0435\u043a\u0435\u043c. Fuzzy (difflib \u22650,90) \u2014 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043b\u044f \u0444\u043b\u0430\u0433\u0430 \u00ab\u043f\u0440\u043e\u0432\u0435\u0440\u0438\u0442\u044c \u0440\u0443\u043a\u0430\u043c\u0438\u00bb, \u043d\u0435 \u0434\u043b\u044f\u81ea\u52a8 \u0437\u0430\u0447\u0451\u0442\u0430: \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u043e\u043a\u0430\u0437\u0430\u043b\u0430, \u0447\u0442\u043e \u043f\u0441\u0435\u0432\u0434\u043e\u043d\u0438\u043c\u043d\u044b\u0435 \u043a\u0435\u0439\u0441\u044b (\u00abThe Rock\u00bb) \u0434\u0430\u044e\u0442 ~0,72, \u0442.\u0435. fuzzy \u0438\u0445 \u043d\u0435 \u043b\u043e\u0432\u0438\u0442, \u0430 \u043f\u043e\u0445\u043e\u0436\u0438\u0435 \u0438\u043c\u0435\u043d\u0430 (\u0431\u0440\u0430\u0442\u044c\u044f/\u0442\u0451\u0437\u043a\u0438) \u043c\u043e\u0433\u0443\u0442 \u043b\u043e\u0436\u043d\u043e \u043b\u043e\u0432\u0438\u0442\u044c\u0441\u044f \u2014 \u043f\u043e\u044d\u0442\u043e\u043c\u0443 aliases \u0438\u0437 \u0441\u043d\u0438\u043c\u043a\u0430 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b.\n\n**\u041e\u0441\u043e\u0431\u044b\u0435 \u0441\u043b\u0443\u0447\u0430\u0438 (\u043f\u0440\u0430\u0432\u0438\u043b\u0430 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430):**\n- \u041e\u0442\u043a\u0430\u0437/\u00ab\u043d\u0435 \u0437\u043d\u0430\u044e\u00bb \u2192 \u043d\u0435\u0432\u0435\u0440\u043d\u043e, \u043d\u043e \u043a\u043e\u0434\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e (\u0434\u043e\u043b\u044f \u043e\u0442\u043a\u0430\u0437\u043e\u0432 \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430; \u0435\u0441\u043b\u0438 \u043e\u0442\u043a\u0430\u0437\u044b \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u044b \u043f\u043e \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u043c, \u044d\u0442\u043e \u0441\u0430\u043c\u043e \u043f\u043e \u0441\u0435\u0431\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442).\n- \u041e\u0442\u0432\u0435\u0442-\u0441\u043f\u0438\u0441\u043e\u043a \u0438\u0437 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u0438\u043c\u0451\u043d: \u0432\u0435\u0440\u043d\u043e, \u0435\u0441\u043b\u0438 \u22651 \u0438\u0437 \u0441\u043f\u0438\u0441\u043a\u0430 \u2208 gold (hit@list) \u2014 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u043e; \u0441\u0442\u0440\u043e\u0433\u043e \u00ab\u0432\u0441\u0435 \u044d\u043b\u0435\u043c\u0435\u043d\u0442\u044b \u2208 gold\u00bb \u2014 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u0430\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u043d\u0430\u044f \u043c\u0435\u0442\u0440\u0438\u043a\u0430.\n- \u0414\u0432\u0443\u0441\u043c\u044b\u0441\u043b\u0435\u043d\u043d\u043e\u0435 \u043a\u043e\u0440\u043e\u0442\u043a\u043e\u0435 \u0438\u043c\u044f (\u00abMichael\u00bb): \u0432\u0435\u0440\u043d\u043e, \u0442\u043e\u043b\u044c\u043a\u043e \u0435\u0441\u043b\u0438 \u043f\u043e\u0441\u043b\u0435 \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u0438 \u044d\u0442\u043e \u043f\u043e\u043b\u043d\u044b\u0439 gold-\u043b\u0435\u0439\u0431\u043b \u0438\u043b\u0438 gold-\u0430\u043b\u0438\u0430\u0441; \u0433\u043e\u043b\u043e\u0435 \u0438\u043c\u044f \u043f\u0440\u0438 \u0441\u043e\u0432\u043f\u0430\u0434\u0435\u043d\u0438\u0438 \u0441 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u043c\u0438 \u0434\u043e\u043f\u0443\u0441\u0442\u0438\u043c\u044b\u043c\u0438 \u0441\u0443\u0449\u043d\u043e\u0441\u0442\u044f\u043c\u0438 \u2014 \u043d\u0435\u0432\u0435\u0440\u043d\u043e + \u0444\u043b\u0430\u0433 \u0430\u0443\u0434\u0438\u0442\u0430.\n- \u00ab\u041f\u0435\u0440\u0435\u043f\u0443\u0442\u0430\u043d\u044b \u0440\u043e\u043b\u0438\u00bb (P-\u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435: \u043c\u043e\u0434\u0435\u043b\u044c \u043d\u0430\u0437\u0432\u0430\u043b \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f) \u2014 \u043d\u0435\u0432\u0435\u0440\u043d\u043e, \u043a\u043e\u0434\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u043e\u0434\u043e\u043c \u043e\u0448\u0438\u0431\u043a\u0438.\n- \u041c\u0443\u043b\u044c\u0442\u0438\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u0441\u043a\u0438\u0439 R (\u0441\u0443\u0440\u0440\u043e\u0433\u0430\u0442\u043d\u044b\u0435/\u043f\u0440\u0438\u0451\u043c\u043d\u044b\u0435 \u2014 \u0441\u043c. \u043f.5 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0443): gold = \u0432\u0441\u0435 \u043d\u0435-deprecated \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f P22/P25 \u043d\u0443\u0436\u043d\u043e\u0433\u043e \u043f\u043e\u043b\u0430.\n\n**\u0420\u0443\u0447\u043d\u043e\u0439 \u0430\u0443\u0434\u0438\u0442:** 10% \u0441\u0442\u0440\u0430\u0442\u0438\u0444\u0438\u0446\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0432\u044b\u0431\u043e\u0440\u043a\u0438 (\u0441\u0442\u0440\u0430\u0442\u044b: \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f \u00d7 \u0438\u0441\u0445\u043e\u0434\u044b \u00ab\u0432\u0435\u0440\u043d\u043e-\u0447\u0435\u0440\u0435\u0437-\u0430\u043b\u0438\u0430\u0441\u00bb, \u00ab\u043e\u0442\u043a\u0430\u0437\u00bb, \u00ab\u0444\u043b\u0430\u0433 fuzzy\u00bb) \u0434\u0432\u0443\u043c\u044f \u0430\u043d\u043d\u043e\u0442\u0430\u0442\u043e\u0440\u0430\u043c\u0438, \u0441\u043b\u0435\u043f\u044b\u043c\u0438 \u043a \u0443\u0441\u043b\u043e\u0432\u0438\u044e-\u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0435; \u0441\u043e\u0433\u043b\u0430\u0441\u0438\u0435 \u041a\u043e\u044d\u043d\u0430 \u043a\u0430\u043f\u043f\u0430 \u22650,8 \u043a\u0430\u043a \u043f\u043e\u0440\u043e\u0433 \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u0430; \u0440\u0430\u0441\u0445\u043e\u0436\u0434\u0435\u043d\u0438\u044f \u2014 \u0442\u0440\u0435\u0442\u0438\u0439 \u0430\u043d\u043d\u043e\u0442\u0430\u0442\u043e\u0440. \u0410\u0443\u0434\u0438\u0442 \u2014 \u0447\u0430\u0441\u0442\u044c \u043f\u0440\u043e\u0442\u043e\u043a\u043e\u043b\u0430 \u0437\u0430\u043f\u0443\u0441\u043a\u0430 (\u0444\u0430\u043a\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0437\u043d\u0430\u0447\u0435\u043d\u0438\u044f \u043a\u0430\u043f\u043f\u044b \u0431\u0443\u0434\u0443\u0442 \u043f\u043e\u043b\u0443\u0447\u0435\u043d\u044b \u043f\u0440\u0438 \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u0438, \u0441\u0435\u0439\u0447\u0430\u0441 \u043d\u0435 \u043f\u0440\u0438\u0432\u043e\u0434\u044f\u0442\u0441\u044f).\n\n## 5. \u0423\u0441\u043b\u043e\u0432\u0438\u044f \u0438 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c\u043d\u044b\u0435 \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u044f\n\n**\u041e\u0421\u041d\u041e\u0412\u041d\u042b\u0415 (\u0432\u044b\u043f\u043e\u043b\u043d\u0438\u043c\u044b \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0435 \u0441\u043d\u0438\u043c\u043a\u0430 + \u043c\u043e\u0434\u0435\u043b\u0435\u0439, \u0431\u0435\u0437 \u043a\u043e\u0440\u043f\u0443\u0441\u0430):**\n- C1: R (\u0440\u0435\u0431\u0451\u043d\u043e\u043a\u2192\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c) vs C2: P (\u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044c\u2192\u0440\u0435\u0431\u0451\u043d\u043e\u043a) \u043d\u0430 \u043e\u0434\u043d\u043e\u043c \u043d\u0430\u0431\u043e\u0440\u0435 \u043f\u0430\u0440 \u2014 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442.\n- C3 (\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438): \u0441\u0442\u0440\u0430\u0442\u044b \u00ab1 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u044b\u0439 \u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb vs \u00ab\u22652\u00bb \u2014 \u0440\u0430\u0437\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u043a\u043e\u043d\u0442\u0440\u0430\u0441\u0442 + \u0432\u0437\u0430\u0438\u043c\u043e\u0434\u0435\u0439\u0441\u0442\u0432\u0438\u0435 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u0435\u00d7N \u0432 \u043c\u043e\u0434\u0435\u043b\u0438.\n- C4 (\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f\u0440\u0438\u0451\u043c\u043d\u044b\u0445 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439, \u043f\u043e \u0432\u0430\u0448\u0435\u043c\u0443 \u043f\u0440\u0435\u0434\u043b\u043e\u0436\u0435\u043d\u0438\u044e): \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0435 \u0443\u0441\u043b\u043e\u0432\u0438\u0435 \u2014 \u0431\u0438\u043e\u043b\u043e\u0433\u0438\u0447\u0435\u0441\u043a\u0438\u0435/\u0443\u0441\u044b\u043d\u043e\u0432\u043b\u044f\u044e\u0449\u0438\u0435 \u0431\u0435\u0437 \u0440\u0430\u0437\u043b\u0438\u0447\u0435\u043d\u0438\u044f, \u043a\u0430\u043a \u0434\u0430\u0451\u0442 P22/P25/P40 (\u044d\u0442\u0438 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 \u0432 Wikidata \u0438\u0445 \u043d\u0435 \u0440\u0430\u0437\u0434\u0435\u043b\u044f\u044e\u0442). \u0427\u0443\u0432\u0441\u0442\u0432\u0438\u0442\u0435\u043b\u044c\u043d\u043e\u0441\u0442\u044c: \u043f\u043e\u0434\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e \u0441 \u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u044b\u043c\u0438 \u043c\u0430\u0440\u043a\u0435\u0440\u0430\u043c\u0438 \u0443\u0441\u044b\u043d\u043e\u0432\u043b\u0435\u043d\u0438\u044f (qualifier P22/P25 \u00abreason rank\u00bb/\u043d\u0430\u0441\u043b\u0435\u0434\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u0441\u0432\u043e\u0439\u0441\u0442\u0432\u0430 \u2014 \u043f\u0440\u043e\u0432\u0435\u0440\u044f\u0435\u0442\u0441\u044f \u043d\u0430 \u044d\u0442\u0430\u043f\u0435 \u043f\u043e\u0441\u0442\u0440\u043e\u0435\u043d\u0438\u044f: \u0435\u0441\u043b\u0438 \u043d\u0430\u0434\u0451\u0436\u043d\u044b\u0445 \u043c\u0430\u0440\u043a\u0435\u0440\u043e\u0432 \u043d\u0435\u0442, \u0432 \u043e\u0442\u0447\u0451\u0442 \u0432\u0445\u043e\u0434\u0438\u0442 \u043a\u043e\u043d\u0441\u0442\u0430\u0442\u0430\u0446\u0438\u044f \u00ab\u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043d\u0435 \u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0435\u043d\u0430\u00bb + \u043e\u0446\u0435\u043d\u043a\u0430 \u0434\u043e\u043b\u0438 \u0441\u043f\u043e\u0440\u043d\u044b\u0445 \u0437\u0430\u043f\u0438\u0441\u0435\u0439 \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435; \u044d\u0442\u043e \u0440\u0435\u0448\u0435\u043d\u0438\u0435 \u043f\u0440\u0438\u043d\u044f\u0442\u043e \u043a\u0430\u043a \u0440\u0430\u0431\u043e\u0447\u0435\u0435).\n- C5 (\u043f\u043b\u0435\u0439\u0446\u0435\u0431\u043e): \u0432\u044b\u043c\u044b\u0448\u043b\u0435\u043d\u043d\u044b\u0435 \u0438\u043c\u0435\u043d\u0430 \u2014 \u0431\u0430\u0437\u043e\u0432\u0430\u044f \u043b\u0438\u043d\u0438\u044f \u0433\u0430\u043b\u043b\u044e\u0446\u0438\u043d\u0430\u0446\u0438\u0439/\u0444\u043e\u0440\u043c\u0430\u0442\u043d\u044b\u0445 \u0441\u0431\u043e\u0435\u0432.\n\n**\u041a\u041e\u041d\u0422\u0420\u041e\u041b\u0418 \u0424\u041e\u0420\u041c\u0423\u041b\u0418\u0420\u041e\u0412\u041a\u0418 (\u043d\u0435 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u044b\u0435):**\n- C6: \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0447\u043d\u044b\u0435 \u0441\u0443\u043f\u0440\u0443\u0433\u0438 (P26, \u043e\u0431\u0430 \u226520 sitelinks) \u0432 \u043e\u0431\u043e\u0438\u0445 \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u0438\u044f\u0445. **\u042f\u0432\u043d\u0430\u044f \u043c\u0430\u0440\u043a\u0438\u0440\u043e\u0432\u043a\u0430:** \u044d\u0442\u043e \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u043d\u0430 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0443 \u043f\u0440\u043e\u043c\u043f\u0442\u0430 \u0438 \u043d\u0430 \u00ab\u0431\u0430\u043b\u0430\u043d\u0441 \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438\u00bb, \u041d\u0415 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0439 \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0438 \u2014 \u0443 \u0441\u0443\u043f\u0440\u0443\u0433\u043e\u0432 \u043e\u0431\u044b\u0447\u043d\u043e \u0441\u0440\u0430\u0432\u043d\u0438\u043c\u0430\u044f \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c \u0438 \u0432\u0437\u0430\u0438\u043c\u043d\u043e\u0435 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0435, \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u043d\u0443\u043b\u0435\u0432\u043e\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 \u0437\u0434\u0435\u0441\u044c \u043d\u0435 \u0434\u043e\u043a\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u0441\u043f\u0435\u0446\u0438\u0444\u0438\u0447\u043d\u043e\u0441\u0442\u044c \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u043d\u043e\u0441\u0442\u0438 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f.\n\n**\u041a\u041e\u041d\u0422\u0420\u041e\u041b\u042c \u041a\u0412\u0410\u0417\u0418-\u0418\u0415\u0420\u0410\u0420\u0425\u0418\u0418 (\u0431\u043e\u043b\u0435\u0435 \u0436\u0451\u0441\u0442\u043a\u0438\u0439, \u0438\u0437 \u0442\u043e\u0433\u043e \u0436\u0435 \u0441\u043d\u0438\u043c\u043a\u0430):**\n- C7: \u0430\u043a\u0430\u0434\u0435\u043c\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u0443\u0447\u0435\u043d\u0438\u043a\u0438 \u2014 P184 (\u00ab\u0443\u0447\u0435\u043d\u0438\u043a\u00bb) / P1066 (\u00ab\u0434\u043e\u043a\u0442\u043e\u0440\u0430\u043d\u0442-\u0443\u0447\u0435\u043d\u0438\u043a\u00bb), \u0431\u0438\u043d\u0430\u0440\u043d\u043e\u0435 \u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0447\u0435\u0441\u043a\u043e\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0435 \u0441 \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u043e\u0439 \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u0435\u0439 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0439 (\u0431\u0438\u043e\u0433\u0440\u0430\u0444\u0438\u044f \u0443\u0447\u0435\u043d\u0438\u043a\u0430 \u0441\u0438\u0441\u0442\u0435\u043c\u043d\u043e \u043d\u0430\u0437\u044b\u0432\u0430\u0435\u0442 \u043d\u0430\u0443\u0447\u043d\u043e\u0433\u043e \u0440\u0443\u043a\u043e\u0432\u043e\u0434\u0438\u0442\u0435\u043b\u044f; \u043e\u0431\u0440\u0430\u0442\u043d\u043e\u0435 \u0440\u0435\u0436\u0435). \u0415\u0441\u043b\u0438 \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u00ab\u0442\u043e\u0447\u043d\u043e\u0441\u0442\u044c \u0432\u043d\u0438\u0437-\u043f\u043e-\u0438\u0435\u0440\u0430\u0440\u0445\u0438\u0438\u2192\u0432\u0432\u0435\u0440\u0445\u00bb \u0432\u043e\u0441\u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u0442\u0441\u044f \u0438 \u0437\u0434\u0435\u0441\u044c \u2014Evidence \u0432 \u043f\u043e\u043b\u044c\u0437\u0443 \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0433\u043e \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430; \u0435\u0441\u043b\u0438 \u043d\u0435\u0442 \u2014 \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 \u0441\u0443\u0436\u0430\u0435\u0442\u0441\u044f \u0434\u043e \u0441\u0435\u043c\u0435\u0439\u043d\u044b\u0445 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u0439. \u0422\u043e\u0442 \u0436\u0435 \u043f\u0430\u0440\u043d\u044b\u0439 \u0434\u0438\u0437\u0430\u0439\u043d \u0438 \u0442\u043e\u0442 \u0436\u0435 \u0441\u043a\u043e\u0440\u0438\u043d\u0433.\n\n**\u041e\u0421\u041d\u041e\u0412\u041d\u041e\u0415 vs \u0423\u0421\u041b\u041e\u0412\u041d\u041e\u0415 \u2014 \u0440\u0430\u0437\u0434\u0435\u043b\u0435\u043d\u0438\u0435 \u043f\u043e \u0431\u043b\u043e\u043a\u0430\u043c:**\n- \u0411\u043b\u043e\u043a A (\u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439, \u0431\u0435\u0437 \u043a\u043e\u0440\u043f\u0443\u0441\u0430): C1\u2013C7 \u0446\u0435\u043b\u0438\u043a\u043e\u043c.\n- \u0411\u043b\u043e\u043a B (**\u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439, \u043f\u0440\u0438 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0435 \u043a\u043e\u0440\u043f\u0443\u0441\u0430**): \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u044b \u0441\u043e\u0432\u043c\u0435\u0441\u0442\u043d\u043e\u0439 \u0432\u0441\u0442\u0440\u0435\u0447\u0430\u0435\u043c\u043e\u0441\u0442\u0438 \u0438\u043c\u0451\u043d \u0438 \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u044f \u0431\u0435\u0440\u0443\u0442\u0441\u044f \u0438\u0437 \u0442\u0435\u043a\u0441\u0442\u043e\u0432 \u0441\u0442\u0430\u0442\u0435\u0439 \u0412\u0438\u043a\u0438\u043f\u0435\u0434\u0438\u0438 (enwiki dump, **\u0442\u043e\u0442 \u0436\u0435 \u043a\u0430\u043b\u0435\u043d\u0434\u0430\u0440\u043d\u044b\u0439 \u0441\u0440\u0435\u0437, \u0447\u0442\u043e \u0438 Wikidata**), \u0430 \u041d\u0415 \u0438\u0437 \u0434\u0430\u043c\u043f\u0430 Wikidata (\u0432 Wikidata \u043d\u0435\u0442 \u0442\u0435\u043a\u0441\u0442\u043e\u0432) \u2014 \u044d\u0442\u043e \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u044b\u0439 \u0442\u0440\u0435\u0431\u0443\u0435\u043c\u044b\u0439 \u0440\u0435\u0441\u0443\u0440\u0441. \u0415\u0441\u043b\u0438 \u043a\u043e\u0440\u043f\u0443\u0441 \u043d\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d, \u0432\u0435\u0441\u044c \u0411\u043b\u043e\u043a B \u043f\u043e\u043c\u0435\u0447\u0430\u0435\u0442\u0441\u044f \u00ab\u043d\u0435 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043e \u2014 \u043a\u043e\u0440\u043f\u0443\u0441 \u043d\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u00bb \u0438 \u0432 \u0432\u044b\u0432\u043e\u0434\u044b \u043d\u0435 \u0432\u0445\u043e\u0434\u0438\u0442.\n- \u0411\u043b\u043e\u043a C (\u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439, \u043f\u0440\u0438 \u0434\u043e\u0441\u0442\u0443\u043f\u043d\u043e\u0441\u0442\u0438): pageview-\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 \u043a\u0430\u043a \u043d\u0435\u043f\u0440\u0435\u0440\u044b\u0432\u043d\u0430\u044f \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u044c (\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u0442\u0434\u0435\u043b\u044c\u043d\u043e\u0433\u043e \u0444\u0430\u0439\u043b\u0430 \u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0438); \u0431\u0435\u0437 \u043d\u0435\u0433\u043e \u2014 \u0442\u043e\u043b\u044c\u043a\u043e sitelinks-\u043f\u0440\u043e\u043a\u0441\u0438.\n- \u0411\u043b\u043e\u043a D (\u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439, \u043f\u0440\u0438 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043c\u043e\u0434\u0435\u043b\u044f\u0445): \u0441\u0440\u0430\u0432\u043d\u0435\u043d\u0438\u0435 \u043c\u043e\u0434\u0435\u043b\u0435\u0439/\u0432\u0435\u0440\u0441\u0438\u0439/\u0440\u0430\u0437\u043c\u0435\u0440\u043e\u0432; \u0431\u0435\u0437 \u043d\u0435\u0433\u043e \u2014 \u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u0430\u044f \u043c\u043e\u0434\u0435\u043b\u044c-\u0440\u0435\u0444\u0435\u0440\u0435\u043d\u0441.\n\n**\u041e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438 (\u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u0440\u0430\u0437\u0434\u0435\u043b\u0435 7, \u043d\u0435 \u0442\u043e\u043b\u044c\u043a\u043e \u0432 \u043d\u0435\u043e\u043f\u0440\u0435\u0434\u0435\u043b\u0451\u043d\u043d\u043e\u0441\u0442\u044f\u0445):** \u0431\u0435\u0437 \u0411\u043b\u043e\u043a\u0430 B \u0434\u0438\u0437\u0430\u0439\u043d \u041d\u0415 \u043f\u043e\u0437\u0432\u043e\u043b\u044f\u0435\u0442 \u043f\u0440\u0438\u043f\u0438\u0441\u0430\u0442\u044c \u043e\u0431\u043d\u0430\u0440\u0443\u0436\u0435\u043d\u043d\u0443\u044e \u0440\u0430\u0437\u043d\u0438\u0446\u0443 \u0438\u0441\u043a\u043b\u044e\u0447\u0438\u0442\u0435\u043b\u044c\u043d\u043e \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044e \u043c\u043e\u0434\u0435\u043b\u0438\u00bb \u2014 \u043e\u043d\u0430 \u043c\u043e\u0436\u0435\u0442 \u043e\u0442\u0440\u0430\u0436\u0430\u0442\u044c \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044e \u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0435\u0433\u043e \u043a\u043e\u0440\u043f\u0443\u0441\u0430 (\u0443\u043f\u043e\u043c\u0438\u043d\u0430\u043d\u0438\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u044f \u0432 \u0441\u0442\u0430\u0442\u044c\u0435 \u0440\u0435\u0431\u0451\u043d\u043a\u0430 \u0438 \u043e\u0431\u0440\u0430\u0442\u043d\u0430\u044f \u0440\u0430\u0437\u0440\u0435\u0436\u0435\u043d\u043d\u043e\u0441\u0442\u044c). \u0424\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 \u0432\u044b\u0432\u043e\u0434\u0430 \u0431\u0435\u0437 \u0411\u043b\u043e\u043a\u0430 B: \u00ab\u043d\u0430\u0431\u043b\u044e\u0434\u0430\u0435\u0442\u0441\u044f \u043d\u0430\u043f\u0440\u0430\u0432\u043b\u0435\u043d\u043d\u0430\u044f \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0438 \u0438\u0437\u0432\u043b\u0435\u0447\u0435\u043d\u0438\u044f; \u0438\u0441\u0442\u043e\u0447\u043d\u0438\u043a (\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 vs \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u0430 \u043a\u043e\u0440\u043f\u0443\u0441\u0430) \u043d\u0435 \u0440\u0430\u0437\u0432\u0435\u0434\u0451\u043d\u00bb.\n\n## 6. \u041f\u043b\u0430\u043d \u0430\u043d\u0430\u043b\u0438\u0437\u0430\n\n1. **\u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442:** \u043e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u0438\u0439 \u0442\u043e\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u041c\u0430\u043a\u041demar \u043d\u0430 \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u044b\u0445 \u043f\u0430\u0440\u0430\u0445 (\u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u2014 \u0431\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u044b\u0439 \u0445\u0432\u043e\u0441\u0442 \u043d\u0430 stdlib; \u0448\u0430\u0431\u043b\u043e\u043d \u043a\u043e\u0434\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d \u0432 \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u0438). \u0414\u0418 \u0434\u043b\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0435\u0439 \u2014 \u0431\u0443\u0442\u0441\u0442\u0440\u0435\u043f\u0430 \u043f\u043e \u043f\u0430\u0440\u0430\u043c (10k, seed \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f).\n2. **\u041c\u043e\u0434\u0435\u043b\u044c \u0441\u043e \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u043c\u0438 \u044d\u0444\u0444\u0435\u043a\u0442\u0430\u043c\u0438:** \u043b\u043e\u0433\u0438\u0441\u0442\u0438\u0447\u0435\u0441\u043a\u0430\u044f \u0441\u043c\u0435\u0448\u0430\u043d\u043d\u0430\u044f `correct ~ direction + template + log_sitelinks(\u0446\u0435\u043b\u044c) + n_candidates + (1|family)` \u2014 \u0441\u043b\u0443\u0447\u0430\u0439\u043d\u044b\u0439 \u043f\u0435\u0440\u0435\u0445\u0432\u0430\u0442 \u043f\u043e \u0441\u0435\u043c\u044c\u0435/\u0441\u0443\u0449\u043d\u043e\u0441\u0442\u0438 \u0443\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442 \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u0438\u0437\u0430\u0446\u0438\u044e (\u043e\u0431\u0449\u0438\u0435 \u0440\u043e\u0434\u0438\u0442\u0435\u043b\u0438/\u0441\u0438\u0431\u0441\u044b \u0432 \u043d\u0435\u0441\u043a\u043e\u043b\u044c\u043a\u0438\u0445 \u043f\u0430\u0440\u0430\u0445); \u043f\u0430\u0440\u043d\u044b\u0439 \u0445\u0430\u0440\u0430\u043a\u0442\u0435\u0440 additionally \u0437\u0430\u043a\u0440\u0435\u043f\u043b\u044f\u0435\u0442\u0441\u044f \u0443\u0441\u043b\u043e\u0432\u043b\u0435\u043d\u0438\u0435\u043c \u043f\u043e \u043f\u0430\u0440\u0435. \u0420\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f: \u043f\u0440\u0438 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0438\u0438 statsmodels \u2014 \u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439 \u0431\u043b\u043e\u043a (\u0447\u0438\u0441\u0442\u044b\u0439 Python IRLS \u0438\u043b\u0438 \u043f\u0435\u0440\u0435\u0445\u043e\u0434 \u043a \u043a\u043b\u0430\u0441\u0442\u0435\u0440\u043d\u043e\u043c\u0443 \u0431\u0443\u0442\u0441\u0442\u0440\u0435\u043f\u0443 \u043f\u043e \u0441\u0435\u043c\u044c\u044f\u043c \u043a\u0430\u043a \u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442; \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u2014 \u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442).\n3. **\u0420\u0430\u0437\u043c\u0435\u0440 \u044d\u0444\u0444\u0435\u043a\u0442\u0430:** Cohen's h \u0434\u043b\u044f \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u0434\u043e\u043b\u0435\u0439 + OR \u0438\u0437 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u041c\u0430\u043a\u041demar (b/c), \u0441 \u0414\u0418.\n4. **\u041c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0435 \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0438:** \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u043e \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u044b\u0445 \u0442\u0435\u0441\u0442\u043e\u0432 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 (\u0441\u0442\u0440\u0430\u0442\u044b C3, C6, C7, \u0448\u0430\u0431\u043b\u043e\u043d\u044b, \u043c\u043e\u0434\u0435\u043b\u0438); \u043f\u043e\u043f\u0440\u0430\u0432\u043a\u0430 Holm\u2013Bonferroni \u043f\u043e \u0432\u0441\u0435\u043c\u0443 \u0432\u0442\u043e\u0440\u0438\u0447\u043d\u043e\u043c\u0443 \u0441\u0435\u043c\u0435\u0439\u0441\u0442\u0432\u0443. \u041f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u043d\u0435 \u043a\u043e\u0440\u0440\u0435\u043a\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f.\n5. **\u041c\u043e\u0449\u043d\u043e\u0441\u0442\u044c \u0438 \u043f\u0440\u0430\u0432\u0438\u043b\u043e \u0444\u0438\u043a\u0441\u0430\u0446\u0438\u0438 N:** \u0434\u043e \u0437\u0430\u043f\u0443\u0441\u043a\u0430 \u2014 \u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u044f \u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0431\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u0430 \u043d\u0430 stdlib (\u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u043f\u0440\u043e\u0432\u0435\u0440\u0435\u043d\u0430 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438); \u043f\u043e\u0441\u043b\u0435 \u043f\u0438\u043b\u043e\u0442\u0430 \u043d\u0430 50 \u043f\u0430\u0440\u0430\u0445 (\u043f\u0438\u043b\u043e\u0442 \u043e\u0446\u0435\u043d\u0438\u0432\u0430\u0435\u0442 \u0442\u043e\u043b\u044c\u043a\u043e \u0434\u043e\u043b\u044e \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u0438 \u0438 \u043a\u0430\u0447\u0435\u0441\u0442\u0432\u043e \u043f\u0430\u0440\u0441\u0438\u043d\u0433\u0430, \u0433\u0438\u043f\u043e\u0442\u0435\u0437\u0430 \u043f\u043e \u043d\u0435\u043c\u0443 \u043d\u0435 \u0442\u0435\u0441\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f) N \u0440\u0430\u0441\u0441\u0447\u0438\u0442\u044b\u0432\u0430\u0435\u0442\u0441\u044f \u043f\u043e\u0434 MDE = 15 \u043f.\u043f. \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u0442\u043e\u0447\u043d\u043e\u0441\u0442\u0435\u0439, \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c 0,80, \u03b1=0,05 \u043e\u0434\u043d\u043e\u0441\u0442\u043e\u0440\u043e\u043d\u043d\u044f\u044f, \u043f\u043e \u043f\u0438\u043b\u043e\u0442\u043d\u043e\u0439 \u0434\u043e\u043b\u0435 \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u0438; \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435 \u0441\u043d\u0438\u0437\u0443 N=250, \u0441\u0432\u0435\u0440\u0445\u0443 N=600 \u043f\u0430\u0440 (\u0432\u0435\u0440\u0445\u043d\u0435\u0435 \u2014 \u0431\u044e\u0434\u0436\u0435\u0442\u043d\u044b\u0439 \u043f\u043e\u0442\u043e\u043b\u043e\u043a, \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f). \u0420\u0430\u0441\u0447\u0451\u0442 \u0438 seed \u0437\u0430\u043d\u043e\u0441\u044f\u0442\u0441\u044f \u0432 \u043f\u0440\u0435\u0440\u0435\u0433\u0438\u0441\u0442\u0440\u0430\u0446\u0438\u044e \u0434\u043e \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0433\u043e \u043f\u0440\u043e\u0433\u043e\u043d\u0430.\n6. **\u0421\u0442\u043e\u0445\u0430\u0441\u0442\u0438\u0447\u043d\u043e\u0441\u0442\u044c:** \u043e\u0441\u043d\u043e\u0432\u043d\u043e\u0439 \u043f\u0440\u043e\u0433\u043e\u043d temperature=0; \u043f\u043e\u0432\u0442\u043e\u0440 3\u00d7 \u043f\u0440\u0438 T=0,7 \u043d\u0430 \u043f\u043e\u0434\u0432\u044b\u0431\u043e\u0440\u043a\u0435 25% \u2014 \u043c\u0435\u0442\u0440\u0438\u043a\u0430 \u0441\u043e\u0433\u043b\u0430\u0441\u043e\u0432\u0430\u043d\u043d\u043e\u0441\u0442\u0438; \u0432 \u043f\u0435\u0440\u0432\u0438\u0447\u043d\u044b\u0439 \u0442\u0435\u0441\u0442 \u0438\u0434\u0451\u0442 temperature=0.\n\n## 7. \u0420\u0435\u0433\u0438\u0441\u0442\u0440 \u0440\u0438\u0441\u043a\u043e\u0432 \u0438 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0439 \u0438\u043d\u0442\u0435\u0440\u043f\u0440\u0435\u0442\u0430\u0446\u0438\u0438\n\n- **R1 (\u0433\u043b\u0430\u0432\u043d\u043e\u0435 \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435):** \u0431\u0435\u0437 \u043a\u043e\u0440\u043f\u0443\u0441\u0430 (\u0411\u043b\u043e\u043a B) \u0430\u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044f \u043d\u0435 \u0430\u0442\u0440\u0438\u0431\u0443\u0442\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u00ab\u0441\u043c\u0435\u0449\u0435\u043d\u0438\u044e \u043c\u043e\u0434\u0435\u043b\u0438\u00bb \u2014 \u0444\u043e\u0440\u043c\u0443\u043b\u0438\u0440\u043e\u0432\u043a\u0430 \u0432\u044b\u0432\u043e\u0434\u0430 \u043e\u0431\u044f\u0437\u0430\u043d\u0430 \u0431\u044b\u0442\u044c \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0435\u043d\u043d\u043e-\u043d\u0435\u0439\u0442\u0440\u0430\u043b\u044c\u043d\u043e\u0439 (\u0441\u043c. \u043f.5).\n- R2: \u0447\u0430\u0441\u0442\u043e\u0442\u043d\u043e\u0441\u0442\u044c/\u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u044c \u2014 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u043f\u043b\u0451\u043d \u0438 \u043a\u043e\u0432\u0430\u0440\u0438\u0430\u0442\u043e\u0439 sitelinks; \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u043e\u0435 \u0441\u043c\u0435\u0448\u0435\u043d\u0438\u0435 \u0441 pageviews \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f (\u0411\u043b\u043e\u043a C \u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0439).\n- R3: P-\u0437\u0430\u043f\u0440\u043e\u0441 \u00aba child\u00bb \u043f\u0440\u0438 N \u0434\u0435\u0442\u0435\u0439 \u2260 R-\u0437\u0430\u043f\u0440\u043e\u0441 \u043f\u043e \u0441\u0442\u0440\u0443\u043a\u0442\u0443\u0440\u043d\u043e\u0439 \u0441\u043b\u043e\u0436\u043d\u043e\u0441\u0442\u0438 \u2014 \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0441\u0442\u0440\u0430\u0442\u043e\u0439 \u00ab\u0435\u0434\u0438\u043d\u0441\u0442\u0432\u0435\u043d\u043d\u044b\u0439 \u0440\u0435\u0431\u0451\u043d\u043e\u043a\u00bb (C3); \u043f\u043e\u043b\u043d\u0430\u044f \u044d\u043a\u0432\u0438\u0432\u0430\u043b\u0435\u043d\u0442\u043d\u043e\u0441\u0442\u044c \u0441\u043b\u043e\u0436\u0434\u043e\u0441\u0442\u0438 \u043d\u0435 \u0434\u043e\u0441\u0442\u0438\u0436\u0438\u043c\u0430 \u2014 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u043a\u0430\u043a \u043e\u0433\u0440\u0430\u043d\u0438\u0447\u0435\u043d\u0438\u0435.\n- R4: P26-\u043a\u043e\u043d\u0442\u0440\u043e\u043b\u044c \u0441\u043c\u0435\u0448\u0438\u0432\u0430\u0435\u0442 \u0441\u0438\u043c\u043c\u0435\u0442\u0440\u0438\u044e \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u0441 \u0431\u0430\u043b\u0430\u043d\u0441\u043e\u043c \u0438\u0437\u0432\u0435\u0441\u0442\u043d\u043e\u0441\u0442\u0438 \u2014 \u043f\u043e\u044d\u0442\u043e\u043c\u0443 \u0434\u043e\u0431\u0430\u0432\u043b\u0435\u043d C7; \u043d\u0438 \u043e\u0434\u0438\u043d \u0438\u0437 \u043d\u0438\u0445 \u043d\u0435 \u044f\u0432\u043b\u044f\u0435\u0442\u0441\u044f \u043f\u043e\u043b\u043d\u044b\u043c \u043a\u043e\u043d\u0442\u0440\u043e\u043b\u0435\u043c \u043c\u0435\u0445\u0430\u043d\u0438\u0437\u043c\u0430.\n- R5: \u043f\u043e\u043a\u0440\u044b\u0442\u0438\u0435 Wikidata \u0441\u043c\u0435\u0449\u0435\u043d\u043e \u043a \u0437\u0430\u043f\u0430\u0434\u043d\u044b\u043c \u0437\u043d\u0430\u043c\u0435\u043d\u0438\u0442\u043e\u0441\u0442\u044f\u043c \u0438 \u043a \u00ab\u0441\u0435\u043c\u0435\u0439\u043d\u044b\u043c \u0434\u0438\u043d\u0430\u0441\u0442\u0438\u044f\u043c\u00bb \u2014 \u0432\u043d\u0435\u0448\u043d\u0438\u0439 \u0432\u0430\u043b\u0438\u0434\u043d\u043e\u0441\u0442\u0438 \u0440\u0438\u0441\u043a; \u0434\u0435\u043a\u043b\u0430\u0440\u0438\u0440\u0443\u0435\u0442\u0441\u044f \u0432 \u043e\u0442\u0447\u0451\u0442\u0435.\n- R6: \u0434\u0430\u0442\u0430 \u0441\u043d\u0438\u043c\u043a\u0430 \u2260 \u043e\u0431\u0443\u0447\u0430\u044e\u0449\u0438\u0439 \u0441\u0440\u0435\u0437 \u043c\u043e\u0434\u0435\u043b\u0438; \u0444\u0430\u043a\u0442\u044b, \u00ab\u0432\u044b\u0443\u0447\u0435\u043d\u043d\u044b\u0435\u00bb \u043c\u043e\u0434\u0435\u043b\u044c\u044e \u043f\u043e\u0437\u0436\u0435 T\u2080 \u0438\u043b\u0438, \u043d\u0430\u043e\u0431\u043e\u0440\u043e\u0442, \u0443\u0441\u0442\u0430\u0440\u0435\u0432\u0448\u0438\u0435 \u0432 \u0441\u043d\u0438\u043c\u043a\u0435, \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u044b \u2014 \u043f\u043e\u043b\u0438\u0442\u0438\u043a\u0430 \u043f.2 \u0441\u043c\u044f\u0433\u0447\u0430\u0435\u0442, \u043d\u0435 \u0443\u0441\u0442\u0440\u0430\u043d\u044f\u0435\u0442.\n- R7: \u043f\u0430\u0440\u0441\u0438\u043d\u0433 \u0441\u0432\u043e\u0431\u043e\u0434\u043d\u044b\u0445 \u043e\u0442\u0432\u0435\u0442\u043e\u0432 \u0434\u0430\u0451\u0442 \u0441\u0438\u0441\u0442\u0435\u043c\u0430\u0442\u0438\u0447\u0435\u0441\u043a\u0438\u0435 \u043e\u0448\u0438\u0431\u043a\u0438 \u043f\u043e \u043d\u0435-\u043b\u0430\u0442\u0438\u043d\u0441\u043a\u0438\u043c \u0438\u043c\u0435\u043d\u0430\u043c \u2014 \u0442\u0440\u0430\u043d\u0441\u043b\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u0430\u044f \u0442\u0430\u0431\u043b\u0438\u0446\u0430 + \u0430\u0443\u0434\u0438\u0442 10%.\n- R8: \u043f\u0440\u0438\u0451\u043c\u043d\u044b\u0435/\u043d\u0435\u0440\u043e\u0434\u043d\u044b\u0435 \u043e\u0442\u043d\u043e\u0448\u0435\u043d\u0438\u044f \u043d\u0435\u0440\u0430\u0437\u043b\u0438\u0447\u0438\u043c\u044b \u0432 gold (C4) \u2014 \u0432\u043e\u0437\u043c\u043e\u0436\u043d\u0430\u044f \u0434\u043e\u043b\u044f \u00ab\u0432\u0435\u0440\u043d\u044b\u0445, \u043d\u043e \u043d\u0435 \u043f\u043e gold\u00bb \u043e\u0442\u0432\u0435\u0442\u043e\u0432; \u043e\u0446\u0435\u043d\u043a\u0430 \u043d\u0430 \u043f\u0438\u043b\u043e\u0442\u0435.\n- R9: \u043f\u043e\u0440\u044f\u0434\u043e\u043a/\u043a\u043e\u043d\u0442\u0435\u043a\u0441\u0442 \u2014 \u0438\u0437\u043e\u043b\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0435 \u0437\u0430\u043f\u0440\u043e\u0441\u044b \u0431\u0435\u0437 \u0438\u0441\u0442\u043e\u0440\u0438\u0438, \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u043e\u0440\u044f\u0434\u043a\u0430; \u0440\u0438\u0441\u043a \u043e\u0441\u0442\u0430\u0442\u043e\u0447\u043d\u044b\u0439 \u0432 API-\u0441\u0435\u0440\u0432\u0435\u0440\u0430\u0445.\n\n## 8. \u041e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u044c: \u0433\u043e\u0442\u043e\u0432\u043e vs \u043e\u0436\u0438\u0434\u0430\u0435\u0442 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432\n\n**\u041c\u043e\u0436\u043d\u043e \u0441\u0434\u0435\u043b\u0430\u0442\u044c \u0443\u0436\u0435 \u0441\u0435\u0439\u0447\u0430\u0441 \u0432 \u0434\u0430\u043d\u043d\u043e\u043c \u0431\u043e\u043a\u0441\u0435 (\u0447\u0438\u0441\u0442\u044b\u0439 stdlib Python; \u043d\u0430 \u043c\u043e\u043c\u0435\u043d\u0442 \u044d\u0442\u043e\u0433\u043e \u0434\u043e\u043a\u0443\u043c\u0435\u043d\u0442\u0430 \u041d\u0415 \u0432\u044b\u043f\u043e\u043b\u043d\u0435\u043d\u043e, \u043a\u0440\u043e\u043c\u0435 \u043c\u0435\u043b\u043a\u0438\u0445 \u043f\u0440\u043e\u0432\u0435\u0440\u043e\u043a \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u0438):**\n- \u041f\u043e\u043b\u043d\u0430\u044f \u0440\u0435\u0430\u043b\u0438\u0437\u0430\u0446\u0438\u044f \u0441\u043a\u043e\u0440\u0438\u043d\u0433\u0430: \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0442\u043e\u0440, \u0441\u043e\u043f\u043e\u0441\u0442\u0430\u0432\u043b\u0435\u043d\u0438\u0435 \u0441 alias-\u043c\u043d\u043e\u0436\u0435\u0441\u0442\u0432\u043e\u043c, \u0430\u0443\u0434\u0438\u0442-\u0432\u044b\u0431\u043e\u0440\u043a\u0430 (difflib, unicodedata \u2014 \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442; \u043f\u0440\u043e\u0432\u0435\u0440\u043a\u0430 \u043f\u043e\u043a\u0430\u0437\u0430\u043b\u0430 \u043d\u0435\u043e\u0431\u0445\u043e\u0434\u0438\u043c\u043e\u0441\u0442\u044c \u0442\u0440\u0430\u043d\u0441\u043b\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u043e\u0439 \u0442\u0430\u0431\u043b\u0438\u0446\u044b \u0438 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442\u0430 aliases \u043d\u0430\u0434 fuzzy).\n- \u0420\u0430\u0441\u0447\u0451\u0442 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438/\u0441\u0438\u043c\u0443\u043b\u044f\u0446\u0438\u044f \u041c\u0430\u043a\u041demar \u0438 \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u043f\u0440\u0430\u0432\u0438\u043b\u0430 N (\u0431\u0438\u043d\u043e\u043c\u0438\u0430\u043b\u044c\u043d\u0430\u044f \u0444\u043e\u0440\u043c\u0443\u043b\u0430 \u043f\u0440\u043e\u0442\u043e\u0442\u0438\u043f\u0438\u0440\u043e\u0432\u0430\u043d\u0430 \u0442\u0435\u0445\u043d\u0438\u0447\u0435\u0441\u043a\u0438).\n- \u041a\u043e\u043d\u0432\u0435\u0439\u0435\u0440 \u0441\u0431\u043e\u0440\u043a\u0438 \u0441\u0442\u0438\u043c\u0443\u043b\u043e\u0432 \u0438\u0437 CSV-\u043f\u0430\u0440 (sqlite3/csv/json), \u0433\u0435\u043d\u0435\u0440\u0430\u0446\u0438\u044f \u0432\u0441\u0435\u0445 \u043f\u0440\u043e\u043c\u043f\u0442-\u0444\u0430\u0439\u043b\u043e\u0432, \u0440\u0430\u043d\u0434\u043e\u043c\u0438\u0437\u0430\u0446\u0438\u044f \u043f\u043e\u0440\u044f\u0434\u043a\u0430 \u0441 \u0444\u0438\u043a\u0441\u0438\u0440\u0443\u0435\u043c\u044b\u043c seed, \u0441\u043a\u0440\u0438\u043f\u0442\u044b \u0430\u043d\u0430\u043b\u0438\u0437\u0430 (\u041c\u0430\u043a\u041demar, \u0431\u0443\u0442\u0441\u0442\u0440\u0435\u043f\u0430, Cohen's h \u2014 \u0432\u0440\u0443\u0447\u043d\u0443\u044e).\n\n**\u0422\u0440\u0435\u0431\u0443\u0435\u0442 \u0432\u043d\u0435\u0448\u043d\u0435\u0439 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 (\u0432 \u0431\u043e\u043a\u0441\u0435 \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u0435\u0442, \u0441\u0435\u0442\u044c \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 \u2014 \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0435\u043d\u043e: socket \u2192 Network is unreachable; \u043c\u043e\u0434\u0435\u043b\u0435\u0439, \u0432\u0435\u0441\u043e\u0432 \u0438 \u0434\u0430\u043c\u043f\u043e\u0432 \u043d\u0430 \u0434\u0438\u0441\u043a\u0435 \u043d\u0435\u0442; numpy/scipy/statsmodels \u043d\u0435 \u0443\u0441\u0442\u0430\u043d\u043e\u0432\u043b\u0435\u043d\u044b):**\n- \u0414\u0430\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0434\u0430\u043c\u043f Wikidata (\u0438\u043b\u0438 \u043f\u0440\u0435\u0434\u044d\u043a\u0441\u043f\u043e\u0440\u0442\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 CSV \u043f\u0430\u0440 + aliases + sitelinks) \u2014 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u0435\u043d (\u0411\u043b\u043e\u043a A).\n- \u0414\u043e\u0441\u0442\u0443\u043f \u043a \u043c\u043e\u0434\u0435\u043b\u044f\u043c: API (\u043d\u0443\u0436\u043d\u0430 \u0441\u0435\u0442\u044c) \u0438\u043b\u0438 \u043b\u043e\u043a\u0430\u043b\u044c\u043d\u044b\u0435 \u0432\u0435\u0441\u0430 (\u043d\u0443\u0436\u043d\u044b \u0444\u0430\u0439\u043b\u044b; CPU-\u0438\u043d\u0444\u0435\u0440\u0435\u043d\u0441 \u043c\u0430\u043b\u044b\u0445 \u043c\u043e\u0434\u0435\u043b\u0435\u0439 \u0442\u0435\u043e\u0440\u0435\u0442\u0438\u0447\u0435\u0441\u043a\u0438 \u0432\u043e\u0437\u043c\u043e\u0436\u0435\u043d \u043d\u0430 224 \u044f\u0434\u0440\u0430\u0445, \u043d\u043e \u0432\u0435\u0441\u043e\u0432 \u043d\u0435\u0442 \u0438 \u0432\u0440\u0435\u043c\u044f \u043f\u0440\u043e\u0433\u043e\u043d\u0430 ~\u0441\u043e\u0442\u0435\u043d \u043f\u0430\u0440 \u00d7 \u0448\u0430\u0431\u043b\u043e\u043d\u043e\u0432 \u00d7 \u043f\u043e\u0432\u0442\u043e\u0440\u043e\u0432 \u043f\u043e\u0442\u0440\u0435\u0431\u0443\u0435\u0442 \u043e\u0446\u0435\u043d\u043a\u0438).\n- enwiki \u043a\u043e\u0440\u043f\u0443\u0441-\u0442\u0435\u043a\u0441\u0442\u044b (\u0411\u043b\u043e\u043a B), pageview-\u0441\u0442\u0430\u0442\u0438\u0441\u0442\u0438\u043a\u0430 (\u0411\u043b\u043e\u043a C), \u0434\u043e\u043f\u043e\u043b\u043d\u0438\u0442\u0435\u043b\u044c\u043d\u044b\u0435 \u043c\u043e\u0434\u0435\u043b\u0438 (\u0411\u043b\u043e\u043a D) \u2014 \u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0435 \u0440\u0435\u0441\u0443\u0440\u0441\u044b.\n- \u0423\u0441\u0442\u0430\u043d\u043e\u0432\u043a\u0430 statsmodels/scipy \u0434\u043b\u044f GLMM (\u0438\u043d\u0430\u0447\u0435 \u2014 \u0437\u0430\u0440\u0430\u043d\u0435\u0435 \u0437\u0430\u0444\u0438\u043a\u0441\u0438\u0440\u043e\u0432\u0430\u043d\u043d\u044b\u0439 \u0437\u0430\u043f\u0430\u0441\u043d\u043e\u0439 \u0432\u0430\u0440\u0438\u0430\u043d\u0442 \u0430\u043d\u0430\u043b\u0438\u0437\u0430).\n\n**\u0418\u0442\u043e\u0433:** \u0411\u043b\u043e\u043a A \u043f\u043e\u043b\u043d\u043e\u0441\u0442\u044c\u044e \u0441\u043f\u0440\u043e\u0435\u043a\u0442\u0438\u0440\u043e\u0432\u0430\u043d \u0438 \u043f\u043e\u0434\u0433\u043e\u0442\u043e\u0432\u043b\u0435\u043d \u043a \u0438\u0441\u043f\u043e\u043b\u043d\u0435\u043d\u0438\u044e \u0441\u0440\u0430\u0437\u0443 \u043f\u043e\u0441\u043b\u0435 \u043f\u043e\u0441\u0442\u0430\u0432\u043a\u0438 \u0434\u0432\u0443\u0445 \u043e\u0431\u044f\u0437\u0430\u0442\u0435\u043b\u044c\u043d\u044b\u0445 \u0440\u0435\u0441\u0443\u0440\u0441\u043e\u0432 (\u0441\u043d\u0438\u043c\u043e\u043a + \u043c\u043e\u0434\u0435\u043b\u0438); \u0411\u043b\u043e\u043a\u0438 B\u2013D \u044f\u0432\u043d\u043e \u043c\u0430\u0440\u043a\u0438\u0440\u0443\u044e\u0442\u0441\u044f \u043a\u0430\u043a \u0443\u0441\u043b\u043e\u0432\u043d\u044b\u0435; \u043d\u0438 \u043e\u0434\u0438\u043d \u0437\u0430\u043f\u0443\u0441\u043a \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430 \u043d\u0435 \u043f\u0440\u043e\u0438\u0437\u0432\u043e\u0434\u0438\u043b\u0441\u044f \u0438 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u043e\u0432 \u043d\u0435 \u043f\u0440\u0438\u0432\u043e\u0434\u0438\u0442\u0441\u044f.", "evidence": "\u041d\u0430\u0431\u043b\u044e\u0434\u0435\u043d\u0438\u044f \u043e\u043a\u0440\u0443\u0436\u0435\u043d\u0438\u044f: /workspace \u0441\u043e\u0434\u0435\u0440\u0436\u0438\u0442 \u0442\u043e\u043b\u044c\u043a\u043e task.json (\u00abdesign-only\u00bb); \u0441\u0435\u0442\u044c \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0451\u043d\u043d\u043e \u043e\u0442\u043a\u043b\u044e\u0447\u0435\u043d\u0430 (socket \u2192 Network is unreachable); numpy/scipy/pandas/statsmodels/torch/transformers \u043e\u0442\u0441\u0443\u0442\u0441\u0442\u0432\u0443\u044e\u0442; \u043c\u043e\u0434\u0435\u043b\u0435\u0439, \u0434\u0430\u043c\u043f\u043e\u0432, \u043a\u044d\u0448\u0435\u0439 \u043d\u0435\u0442; stdlib-\u043c\u043e\u0434\u0443\u043b\u0438 (sqlite3, csv, json, difflib, unicodedata, math) \u0440\u0430\u0431\u043e\u0442\u0430\u044e\u0442. \u041f\u0440\u043e\u0432\u0435\u0440\u043a\u0438 \u043e\u0441\u0443\u0449\u0435\u0441\u0442\u0432\u0438\u043c\u043e\u0441\u0442\u0438 (\u043d\u0435 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u044b \u044d\u043a\u0441\u043f\u0435\u0440\u0438\u043c\u0435\u043d\u0442\u0430): (1) \u043f\u0440\u043e\u0442\u043e\u0442\u0438\u043f \u043d\u043e\u0440\u043c\u0430\u043b\u0438\u0437\u0430\u0442\u043e\u0440\u0430 \u043d\u0430 stdlib \u2014 NFKD-\u0434\u0435\u043a\u043e\u043c\u043f\u043e\u0437\u0438\u0446\u0438\u044f \u043d\u0435 \u0441\u043d\u0438\u043c\u0430\u0435\u0442 \u0447\u0430\u0441\u0442\u044c \u0441\u0438\u043c\u0432\u043e\u043b\u043e\u0432 (\u00f0 \u043e\u0441\u0442\u0430\u0451\u0442\u0441\u044f), fuzzy-\u0441\u043a\u043e\u0440 \u0434\u043b\u044f \u043f\u0441\u0435\u0432\u0434\u043e\u043d\u0438\u043c\u0430 \u00abDwayne 'The Rock' Johnson\u00bb vs \u00abdwayne johnson\u00bb = 0,718 (<0,9), \u043e\u0431\u044b\u0447\u043d\u044b\u0439 \u043a\u0435\u0439\u0441 \u00abBj\u00f6rk\u00bb = 0,95 \u2014 \u044d\u0442\u043e \u043e\u0431\u043e\u0441\u043d\u043e\u0432\u044b\u0432\u0430\u0435\u0442 \u043f\u0440\u0438\u043e\u0440\u0438\u0442\u0435\u0442 aliases \u0438\u0437 \u0441\u043d\u0438\u043c\u043a\u0430 \u0438 \u0442\u0440\u0430\u043d\u0441\u043b\u0438\u0442\u0435\u0440\u0430\u0446\u0438\u043e\u043d\u043d\u0443\u044e \u0442\u0430\u0431\u043b\u0438\u0446\u0443 \u0432 \u043f.4; (2) \u043f\u0440\u043e\u0442\u043e\u0442\u0438\u043f \u0442\u043e\u0447\u043d\u043e\u0433\u043e \u0440\u0430\u0441\u0447\u0451\u0442\u0430 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u0438 \u041c\u0430\u043a\u041demar \u043d\u0430 math.comb \u043e\u0442\u0440\u0430\u0431\u043e\u0442\u0430\u043b (\u0434\u043b\u044f 14 \u043f.\u043f. \u0440\u0430\u0437\u043d\u0438\u0446\u044b \u0438 26% \u0434\u0438\u0441\u043a\u043e\u0440\u0434\u0430\u043d\u0442\u043d\u043e\u0441\u0442\u0438 \u043c\u043e\u0449\u043d\u043e\u0441\u0442\u044c ~1.0 \u0443\u0436\u0435 \u043f\u0440\u0438 N=100, \u0447\u0442\u043e \u043f\u043e\u0434\u0442\u0432\u0435\u0440\u0436\u0434\u0430\u0435\u0442 \u043a\u043e\u043d\u0441\u0435\u0440\u0432\u0430\u0442\u0438\u0432\u043d\u043e\u0441\u0442\u044c \u0432\u044b\u0431\u043e\u0440\u0430 MDE=15 \u043f.\u043f. \u0438 \u043d\u0438\u0436\u043d\u0435\u0439 \u0433\u0440\u0430\u043d\u0438\u0446\u044b N=250 \u0432 \u043f.6); (3) \u0442\u0440\u0435\u043a-\